contract.head:
#version 300 es
precision highp float;
uniform vec2 u_res;
uniform float u_dpr;
uniform vec3 u_pal[6];
uniform float u_dark;
uniform float u_grain;
uniform float u_opt;
uniform vec2 u_tilt;
uniform float u_tg;
uniform vec2 u_light;
uniform vec2 u_light0;
uniform float u_lw;
uniform float u_focus;
out vec4 o;

contract.lib:
const float PI = 3.14159265;
float sat(float x){ return clamp(x, 0., 1.); }
float s01(float a, float b, float x){ return smoothstep(a, b, x); }
float pxu(){ return 2./u_res.y; }
float cssu(){ return 2.*u_dpr/u_res.y; }
mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }
float h21(vec2 p){ vec3 q = fract(vec3(p.xyx)*.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y)*q.z); }
vec2 h22(vec2 p){ vec3 q = fract(vec3(p.xyx)*vec3(.1031, .1030, .0973)); q += dot(q, q.yzx + 33.33); return fract((q.xx + q.yz)*q.zy); }
float gn(vec2 p){
  vec2 i = floor(p), f = p - i;   // not fract(p): on an exact integer the two can disagree and a whole row jumps a cell
  vec2 u = f*f*f*(f*(f*6. - 15.) + 10.);
  float a = dot(h22(i)*2. - 1., f);
  float b = dot(h22(i + vec2(1., 0.))*2. - 1., f - vec2(1., 0.));
  float c = dot(h22(i + vec2(0., 1.))*2. - 1., f - vec2(0., 1.));
  float d = dot(h22(i + vec2(1., 1.))*2. - 1., f - vec2(1., 1.));
  return 1.6*mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(vec2 p){ float s = 0., a = .5; for (int i = 0; i < 5; i++) { s += a*gn(p); p = mat2(1.6, 1.2, -1.2, 1.6)*p + vec2(1.7, 9.2); a *= .5; } return s; }
float fbm3(vec2 p){ float s = 0., a = .5; for (int i = 0; i < 3; i++) { s += a*gn(p); p = mat2(1.6, 1.2, -1.2, 1.6)*p + vec2(1.7, 9.2); a *= .5; } return s; }
float sm1(float x){ x = sat(x); return mix(x, x*x*(3. - 2.*x), .6); }
vec3 ramp(float t){ t = sat(t)*4.; vec3 c = mix(u_pal[0], u_pal[1], sm1(t)); c = mix(c, u_pal[2], sm1(t - 1.)); c = mix(c, u_pal[3], sm1(t - 2.)); return mix(c, u_pal[4], sm1(t - 3.)); }
vec3 dim(vec3 c, float k){ return vec3(c.x*(1. - k), c.yz*(1. - .3*k)); }
vec3 lift(vec3 c, float k){ return vec3(c.x + k, c.yz*(1. - .6*sat(k*2.))); }
float cover(float d){ float w = pxu(); return 1. - smoothstep(-w, w, d); }
float sdBox(vec2 p, vec2 b, float r){ vec2 q = abs(p) - b + r; return length(max(q, 0.)) + min(max(q.x, q.y), 0.) - r; }

wallpapers.src:
float rEdge(float x, float i){
  return .8 - i*.3 + .15*sin(x*.95 + i*1.9 + .4) + .085*sin(x*2.1 - i*2.7 + 1.3) + .03*gn(vec2(x*1.3 + i*7.1, i*3.3));
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], u_pal[0], sat(.55 - p.y*.45));
  float soft = mix(.035, .15, u_opt);
  for (int k = 0; k < 7; k++) {
    float i = float(k);
    float e = .01;
    float y = rEdge(p.x, i);
    float sl = (rEdge(p.x + e, i) - rEdge(p.x - e, i))/(2.*e);
    float d = (p.y - y)/sqrt(1. + sl*sl);
    float a = cover(d);
    col = dim(col, mix(.38, .55, u_dark)*exp(-max(d, 0.)/soft)*(1. - a));
    vec3 c = ramp(i/6. + .05*sin(p.x*.8 + i*2.));
    float dep = max(-d, 0.);
    c = dim(c, .34*s01(0., .5, dep));
    c.x += .075*exp(-dep/.03) + .03*exp(-dep/.12);
    col = mix(col, c, a);
  }
  col.x += .035*s01(1.8, -1.2, p.x - p.y*.6);
  return col;
}

vec3 wall(vec2 p){
  vec2 O = vec2(-2.05, -1.5);
  vec3 col = mix(u_pal[5], dim(u_pal[5], .35), sat(length(p - vec2(1.3, .9))*.42));
  float step_ = mix(.118, .158, u_opt);
  for (int k = 0; k < 10; k++) {
    float i = float(k);
    float th = .1 + i*step_;
    vec2 q = rot(-th)*(p - O);
    q.y -= .045*q.x*q.x - .12*q.x;
    float Lp = 4.5 + .35*sin(i*1.7);
    float s = q.x/Lp;
    float w = (.4 + .05*sin(i*2.3))*pow(sat(sin(PI*sat(s))), .62);
    float d = max(abs(q.y) - w, max(-q.x, q.x - Lp));
    vec2 qs = rot(-th)*(p - O - vec2(.045, -.06));
    qs.y -= .045*qs.x*qs.x - .12*qs.x;
    float ws = (.4 + .05*sin(i*2.3))*pow(sat(sin(PI*sat(qs.x/Lp))), .62);
    float sh = 1. - s01(-.05, .11, abs(qs.y) - ws);
    float a = cover(d*.85);
    col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
    float ny = clamp(q.y/max(w, 1e-3), -1.2, 1.2);
    vec3 c = ramp(i/9. + .1*(s - .5));
    c = dim(c, .3*(1. - s01(.25, .75, s)));
    c.x += .05*ny - .04*ny*ny;
    float edge = max(w - abs(q.y), 0.);
    c.x += (ny > 0. ? .06 : .02)*exp(-edge/.012);
    c.x += .03*exp(-edge/.07);
    col = mix(col, c, a);
  }
  return col;
}

vec3 bgP(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .32*p.x - .3*p.y));
  c = mix(c, u_pal[5], .55*s01(-.25, -1.15, p.y));
  vec2 oc = vec2(.38, .12);
  float r = length(p - oc);
  c = mix(c, u_pal[4], .65*exp(-r*r*1.5));
  vec3 orb = mix(u_pal[3], u_pal[2], sm1(r/.58));
  orb.x += .06*s01(.55, .0, length(p - oc - vec2(-.16, .2)));
  c = mix(c, orb, 1. - s01(.5, .64, r));
  float r2 = length(p - vec2(-.82, -.42));
  c = mix(c, mix(u_pal[4], u_pal[2], sm1(r2/.3)), (1. - s01(.22, .34, r2))*.9);
  return c;
}
vec3 wall(vec2 p){
  float fw = mix(.035, .12, u_opt);
  float fx = p.x/fw;
  float cx = (floor(fx) + .5)*fw;
  float f = fract(fx) - .5;
  float xs = cx - 1.6*fw*sin(f*PI);
  vec3 acc = vec3(0.);
  for (int j = 0; j < 6; j++) {
    float a = float(j)*1.047 + .3;
    acc += bgP(vec2(xs, p.y) + vec2(.04, .025)*vec2(cos(a), sin(a)));
  }
  vec3 c = acc/6.;
  float hl = exp(-pow((f + .27)/.07, 2.));
  float seam = exp(-(.5 - abs(f))/.018);
  c.x += .03*hl - .03*seam + .03*cos(f*PI) - .015;
  c.yz *= 1. - .2*hl;
  return c;
}

float ridgeS(float x, float i){
  float s = 0., a = .5, f = 1.;
  for (int o = 0; o < 5; o++) {
    s += a*(1. - abs(gn(vec2(x*f + i*13.7, i*5.3 + float(o)*3.1))));
    f *= 2.07; a *= .47;
  }
  return s;
}
vec3 wall(vec2 p){
  float hz = -.12;
  float t = sat((p.y - hz)/1.15);
  vec3 sky = mix(u_pal[0], u_pal[1], sm1(t*2.4));
  sky = mix(sky, u_pal[2], sm1(t*2. - .6));
  sky = mix(sky, u_pal[3], sm1(t*1.7 - .75));
  vec2 sp = vec2(.42, hz + .17);
  float sr = length(p - sp);
  sky = mix(sky, u_pal[4], .5*exp(-sr*2.2) + .3*exp(-sr*8.));
  vec3 col = mix(sky, lift(u_pal[4], .02), cover(sr - .085));
  float hzA = mix(.45, 1., u_opt);
  for (int k = 0; k < 5; k++) {
    float i = float(k);
    float u = i/4.;
    vec2 q = p + u_tilt*(.3 + .7*u);
    float base = hz + .2 - i*.2;
    float amp = .2 + i*.06;
    float sc = .5 + i*.08;
    float e = .006;
    float y = base + amp*(ridgeS(q.x*sc, i) - .62);
    float y2 = base + amp*(ridgeS((q.x + e)*sc, i) - .62);
    float sl = (y2 - y)/e;
    float a = cover((q.y - y)/sqrt(1. + sl*sl));
    float far = 1. - i/4.;
    vec3 m = mix(mix(u_pal[0], u_pal[1], .55), u_pal[1], sm1(u*2.));
    m = mix(m, u_pal[2], sm1(u*2. - .6));
    m = mix(m, u_pal[5], sm1(u*1.6 - .55));
    m = dim(m, .18 + .12*u);
    m = mix(m, u_pal[0], far*far*hzA*.55);
    m = mix(m, u_pal[4], .28*far*exp(-length(p - sp)*1.2));
    float dep = max(y - q.y, 0.);
    m = mix(m, mix(u_pal[0], u_pal[1], .6), hzA*.38*s01(.0, .3, dep)*(.3 + .7*far));
    m.x += .08*exp(-dep/.007)*exp(-abs(p.x - sp.x)*.8)*(.35 + .65*far);
    col = mix(col, m, a);
  }
  return col;
}

float curtainB(vec2 p, float seed, float yb, float h){
  float c = yb + .2*sin(p.x*.9 + seed) + .12*sin(p.x*2.1 + seed*2.3) + .05*gn(vec2(p.x*2.6, seed));
  float up = p.y - c;
  float wx = p.x + .2*up*sin(p.x*1.3 + seed);
  float r = .5 + .5*gn(vec2(wx*9. + 2.2*gn(vec2(wx*1.3, seed + 4.)), up*.3 + seed*2.));
  float env = s01(-.3, .5, gn(vec2(p.x*.6 + seed*3., seed)));
  float core = (up > 0. ? exp(-up/h) : exp(up/.03))*(.15 + .85*r*r*r)*(1. + .9*exp(-max(up, 0.)/.04));
  float glow = exp(-abs(up - .12)/.32)*.3;
  return (core*1.9 + glow)*env;
}
vec3 skyB(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[5], s01(-.45, 1., p.y));
  vec2 cell = floor(p/.045);
  vec2 sp = (cell + .2 + .6*h22(cell))*.045;
  float sz = max(.0011, cssu()*.45)*(.6 + 1.1*h21(cell + 3.1));
  float on = step(.78, h21(cell + 9.7));
  c.x += .5*on*exp(-dot(p - sp, p - sp)/(sz*sz))*u_dark*s01(-.25, .5, p.y);
  float k = mix(.7, 1.5, u_opt);
  float i1 = curtainB(p, 1.3, .02, .34)*k;
  float i2 = curtainB(p*vec2(1.2, 1.) + vec2(2.3, 0.), 7.9, .36, .3)*k*.75;
  vec3 a1 = mix(u_pal[1], u_pal[2], s01(.0, .65, p.y + .02));
  vec3 a2 = mix(u_pal[3], u_pal[2], s01(.25, .85, p.y));
  c = mix(c, a1, sat(i1*1.1));
  c = mix(c, a2, sat(i2));
  c.x += .12*sat(i1 + i2)*u_dark;
  c = mix(c, u_pal[1], .12*k*exp(-abs(p.y + .3)*3.5));
  return c;
}
float ridgeB(float x){
  float s = 0., a = .5, f = 1.;
  for (int o = 0; o < 4; o++) { s += a*(1. - abs(gn(vec2(x*f*.8 + 4.1, float(o)*2.3)))); f *= 2.1; a *= .5; }
  return -.43 + .2*s - .05*x*x*.1;
}
vec3 sceneB(vec2 p){
  vec3 c = skyB(p);
  float d = p.y - ridgeB(p.x);
  vec3 m = mix(u_pal[4], u_pal[0], .3*s01(-.15, 0., d));
  m.x += .05*exp(-abs(d)/.006)*u_dark;
  return mix(c, m, cover(d));
}
vec3 wall(vec2 p){
  float lake = -.45;
  vec3 c = sceneB(p);
  if (p.y < lake + .01) {
    float w = .006*gn(vec2(p.x*3., p.y*55.)) + .004*gn(vec2(p.x*9., p.y*120.));
    vec2 rp = vec2(p.x + w, 2.*lake - p.y + w*2.);
    vec3 r = dim(sceneB(rp), mix(.1, .28, u_dark));
    r = mix(r, u_pal[4], mix(.15, .3, u_dark)*s01(lake, lake - .55, p.y));
    c = mix(c, r, cover(p.y - lake));
  }
  return c;
}

float hS(vec2 p){
  vec2 q = rot(.35)*p;
  q += .28*vec2(sin(q.y*1.3 + .5), sin(q.x*1.1 + 1.7));
  float w = 1.6*sin(q.y*1.1 + .4) + .8*sin(q.y*2.3 - q.x*.5);
  return .5*sin(q.x*3.4 + w) + .25*sin(q.x*6.1 + 1.3*w - q.y*1.1) + .2*sin(q.y*2.9 + q.x*1.2);
}
vec3 wall(vec2 p){
  float e = .003, amp = mix(.3, .75, u_opt);
  float h0 = hS(p), hx = hS(p + vec2(e, 0.)), hy = hS(p + vec2(0., e));
  vec3 n = normalize(vec3(-(hx - h0)/e*amp, -(hy - h0)/e*amp, 1.));
  vec3 Ld = normalize(vec3(-.5, .62, .6));
  float dif = dot(n, Ld);
  vec3 H = normalize(Ld + vec3(0., 0., 1.));
  float nh = clamp(dot(n, H), 0., 1.);
  float t = .5 + .45*sin(p.x*.55 - p.y*.4 + h0*.5);
  vec3 c = ramp(t);
  c.yz = rot(n.x*.9 - n.y*.5)*c.yz;
  float occ = sat(dif*.9 + .1);
  c = mix(c, u_pal[5], .7*(1. - occ)*(1. - occ));
  c.x *= .78 + .3*occ;
  c.x += .16*pow(nh, 26.) + .12*pow(nh, 160.);
  c.yz *= 1. - .4*pow(nh, 26.);
  return c;
}

vec3 studio(vec2 p){
  float t = s01(-.42, .2, p.y + .04*p.x);
  vec3 fl = mix(lift(u_pal[5], .035), u_pal[5], s01(-1., -.25, p.y));
  vec3 wl = mix(u_pal[5], dim(u_pal[5], .28), s01(-.1, 1.1, p.y));
  vec3 c = mix(fl, wl, t);
  c.x += .055*exp(-dot(p - vec2(-.55, .15), p - vec2(-.55, .15))*.3) - .035*s01(.4, 1.8, p.x);
  return c;
}
void ball(inout vec3 col, vec2 p, vec2 g, float r, vec3 bc, float bl){
  vec2 c = g + vec2(0., r);
  vec2 q = (p - c)/r;
  float d = length(p - c) - r;
  float aa = pxu()*1.3 + bl;
  float a = 1. - smoothstep(-aa, aa, d);
  vec2 sq = (p - g - vec2(.62*r, .2*r))/vec2(1.35*r, .36*r);
  float soft = exp(-dot(sq, sq)*1.2);
  vec2 cq = (p - g - vec2(.08*r, 0.))/vec2(.62*r, .1*r);
  float cont = exp(-dot(cq, cq)*1.5);
  col = dim(col, (mix(.26, .4, u_dark)*soft + mix(.42, .55, u_dark)*cont)*(1. - a));
  vec2 bq = (p - g)/vec2(1.3*r, .35*r);
  col.yz = mix(col.yz, bc.yz, .22*exp(-dot(bq, bq))*(1. - a));
  float z = sqrt(max(1. - dot(q, q), 0.));
  vec3 n = normalize(vec3(q, z + .002));
  vec3 K = normalize(vec3(-.62, .55, .56)), F = normalize(vec3(.85, .05, .5));
  float kw = sat(dot(n, K)*.62 + .38);
  kw = kw*kw*(3. - 2.*kw);
  float fw = sat(dot(n, F))*.2;
  float bo = sat(-n.y)*.22;
  vec3 b = vec3(bc.x*(.34 + .64*kw + fw + .25*bo), bc.yz*(1. + .55*kw*(1. - kw) + .12*(1. - kw) - .18*kw*kw));
  b.x += .045*(1. - kw)*pow(1. - z, 1.5);
  b = mix(b, studio(vec2(p.x, g.y - .1)), .22*bo);
  vec3 R = vec3(2.*n.z*n.x, 2.*n.z*n.y, 2.*n.z*n.z - 1.);
  float gl = mix(.3, 1., u_opt);
  vec3 env = mix(dim(u_pal[5], .15), lift(u_pal[5], .1), s01(-.25, .25, R.y));
  float fr = pow(1. - z, 3.);
  b = mix(b, env, (.08 + .42*gl)*fr);
  float box = sdBox(R.xy - vec2(-.44, .42), vec2(.24, .16), .13);
  float sb = (1. - s01(-.14, .12, box))*s01(-.1, .35, R.z);
  b = mix(b, vec3(min(b.x + .3, .975), b.yz*.5), sb*gl*.7);
  float fb = (1. - s01(-.1, .1, sdBox(R.xy - vec2(.62, .02), vec2(.05, .2), .05)))*s01(-.1, .3, R.z);
  b.x += .06*fb*gl;
  col = mix(col, b, a);
}
vec3 wall(vec2 p){
  vec3 col = studio(p);
  ball(col, p, vec2(1.08, -.1), .11, u_pal[4], .006);
  ball(col, p, vec2(-.1, -.16), .17, u_pal[3], .004);
  ball(col, p, vec2(-1.08, -.36), .31, u_pal[1], .002);
  ball(col, p, vec2(.6, -.62), .46, u_pal[0], 0.);
  ball(col, p, vec2(-.42, -.9), .29, u_pal[2], .003);
  ball(col, p, vec2(1.45, -.96), .25, u_pal[4], .005);
  return col;
}

float shoreL(float x){ return -.5 + .22*sin(x*.8 + .6) + .1*sin(x*1.9 - 1.) + .04*gn(vec2(x*2.5, 3.)); }
vec3 wall(vec2 p){
  float sy = shoreL(p.x);
  float up = p.y - sy;
  float D = .84 - .62*sat(up*.75) + .16*fbm(p*.9 + vec2(3., 1.)) - .1*s01(.5, 1.6, up);
  vec3 c = ramp(sat(D*1.12 - .05));
  float reef = s01(.12, .35, fbm(p*1.6 + 9.))*s01(.2, .5, up)*s01(1.5, .7, up);
  c = dim(c, .22*reef);
  c.yz = mix(c.yz, u_pal[1].yz, .25*reef);
  vec2 q = p*vec2(.9, 1.15);
  vec2 w = q*3.4 + .9*vec2(gn(q*1.3), gn(q*1.3 + 5.2));
  float ca = exp(-abs(gn(w))*9.) + .6*exp(-abs(gn(w*1.65 + 2.3))*11.);
  float shal = s01(.35, .85, D)*s01(-.01, .04, up);
  c.x += mix(.03, .12, u_opt)*ca*shal;
  c.yz *= 1. - .2*ca*shal*u_opt;
  float edge = up + .012*gn(vec2(p.x*9., 1.));
  float sand = cover(edge);
  vec3 sd = u_pal[4];
  sd.x += .02*gn(p*7.) - .06*s01(-.08, 0., edge);
  sd = mix(sd, dim(u_pal[3], .15), .4*s01(-.06, 0., edge));
  c = mix(c, sd, sand);
  float foam = exp(-abs(edge - .006)/.006) + .55*exp(-abs(edge - .055 - .01*gn(vec2(p.x*4., 7.)))/.007) + .3*exp(-abs(edge - .12 - .02*gn(vec2(p.x*3., 2.)))/.008);
  foam *= .55 + .45*gn(p*vec2(18., 40.));
  c = mix(c, u_pal[5], sat(foam)*.75*(1. - sand));
  return c;
}

vec3 wall(vec2 p){
  vec2 O = vec2(.0, -1.32);
  vec2 q = p - O;
  float r = length(q);
  float a = atan(q.x, q.y);
  float N = mix(5., 9., u_opt);
  float s = (a + .1*r)*N/PI*2.;
  float x = cos(s*PI);
  float ws = pxu()*N*2./max(r, .05);
  float fold = x/(abs(x) + .035 + ws*2.5);
  vec3 c = ramp(.5 + a*.37 + .03*r);
  c = dim(c, .26*s01(.3, 2.6, r));
  c.x += .055*fold*(1. - .4*exp(-r)) - .015*(1. - abs(fold));
  c.yz *= 1. - .1*fold;
  float g = exp(-r*1.15);
  c = mix(c, u_pal[5], .8*g*g + .25*g);
  return c;
}

vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], .05), dim(u_pal[5], .35), sat(.42 - p.y*.3 + p.x*.1));
  col.x += .03*fbm3(p*1.6)*u_dark;
  vec2 P0 = vec2(-.62, .3);
  vec2 dIn = normalize(P0 - vec2(-2.2, .95));
  vec2 v = p - P0;
  float along = dot(v, dIn), across = dot(v, vec2(-dIn.y, dIn.x));
  float Iin = exp(-across*across/(.0007 + .0004*u_opt))*s01(.04, -.08, along);
  float ang = atan(v.y, v.x);
  float spread = mix(.35, .75, u_opt);
  float a0 = -.2 - spread;
  float t = (ang - a0)/spread;
  float r = length(v);
  float soft = .025 + .05/(1. + r*3.);
  float fan = s01(-soft*4., soft*4., t)*s01(1. + soft*4., 1. - soft*4., t)*s01(.0, .25, r);
  float haze = .6 + .4*fbm3(vec2(ang*14., r*1.1 + 3.));
  float I = fan*haze*exp(-r*.32);
  float bloom = s01(-.6, .5, t)*s01(1.6, .5, t)*exp(-r*.5)*.22;
  col = mix(col, ramp(sat(t)), sat(bloom));
  col = mix(col, ramp(sat(t)), sat(I*1.5));
  col.x += .14*I*u_dark;
  col = mix(col, lift(u_pal[2], .2), sat(Iin*.9));
  col.x += mix(.12, .25, u_dark)*exp(-r*r*120.);
  return col;
}

float dkmF(){ return 1. - s01(.3, .7, u_pal[5].x); }
vec4 paneG(float i){
  if (i < .5) return vec4(.62, .3, .26, .78);
  if (i < 1.5) return vec4(1.02, .12, .28, .82);
  if (i < 2.5) return vec4(1.42, -.08, .27, .8);
  if (i < 3.5) return vec4(-1.32, -.42, .3, .62);
  return vec4(-.92, -.72, .2, .44);
}
float paneA(float i){ return i < .5 ? -.2 : i < 1.5 ? -.1 : i < 2.5 ? .02 : i < 3.5 ? .16 : .26; }
float paneD(vec2 p, float i){ vec4 g = paneG(i); return sdBox(rot(paneA(i))*(p - g.xy), g.zw, .022); }
vec2 paneQ(vec2 p, float i){ vec4 g = paneG(i); return rot(paneA(i))*(p - g.xy)/g.zw; }
vec3 faceC(float i, vec2 q){ return mix(ramp(fract(i*.27)), ramp(fract(i*.27 + .5)), sm1(sat(.5 + .45*q.y + .2*q.x))); }
vec3 castC(float i, vec2 q){ return mix(ramp(fract(i*.27 + .5)), ramp(fract(i*.27 + .7)), sm1(sat(.5 - .4*q.y))); }
vec3 wallD(vec2 p){
  vec2 sp = vec2(-1.1, 1.05);
  float r = length(p - sp);
  vec3 c = mix(lift(u_pal[5], mix(.025, .11, dkmF())), dim(u_pal[5], mix(.1, .32, dkmF())), sat(r*.36));
  float k = mix(.35, 1., u_opt);
  vec2 off = vec2(.16, -.13);
  for (int j = 0; j < 5; j++) {
    float i = float(j);
    vec2 q = p - off*(1. + .25*mod(i*1.3, 1.));
    float d = paneD(q, i);
    float soft = .012 + .02*sat(-d*2.);
    float inside = 1. - s01(-soft, soft, d);
    vec3 t = castC(i, paneQ(q, i));
    vec3 lit = vec3(mix(c.x, t.x + .08, mix(.25, .55, dkmF())), mix(c.yz, t.yz*1.3, .85));
    c = mix(c, lit, inside*k);
    c.x += k*mix(.06, .12, dkmF())*exp(-abs(d + .01)/.008)*(1. - s01(-.1, .3, dot(normalize(q - paneG(i).xy), normalize(off))));
  }
  return c;
}
vec3 wall(vec2 p){
  vec3 col = wallD(p);
  vec2 Ld = normalize(vec2(-.62, .78));
  for (int j = 0; j < 5; j++) {
    float i = float(j);
    float d = paneD(p, i);
    float a = cover(d);
    if (a > 0.) {
      float e = .002;
      vec2 n = normalize(vec2(paneD(p + vec2(e, 0.), i) - paneD(p - vec2(e, 0.), i), paneD(p + vec2(0., e), i) - paneD(p - vec2(0., e), i)) + 1e-6);
      float ins = max(-d, 0.);
      vec3 under = wallD(p + n*.03*exp(-ins/.03));
      vec2 q = paneQ(p, i);
      vec3 f = faceC(i, q);
      vec3 tr = vec3(mix(under.x*(.7 + .3*f.x), f.x, mix(.35, .6, dkmF())), mix(under.yz, f.yz*1.1, .72));
      float sheen = exp(-pow((q.x*.5 + q.y*.85 - .45)/.35, 2.));
      tr.x += mix(.06, .1, dkmF())*sheen;
      tr.yz *= 1. - .2*sheen;
      float facing = sat(dot(n, Ld));
      float rim = exp(-ins/.0045);
      tr.x += rim*(.18*facing + .04) - .06*exp(-abs(ins - .011)/.004)*(1. - facing);
      tr.x += .04*exp(-ins/.022)*facing;
      tr.yz *= 1. - .4*rim*facing;
      col = mix(col, tr, a);
    }
  }
  return col;
}

float dkmF(){ return 1. - s01(.3, .7, u_pal[5].x); }
float cY(float x, float k){ return k < .5 ? -.25 + .3*sin(.78*x + .2) + .1*sin(1.7*x - 1.) + .12*x : .42 + .22*sin(.9*x + 2.4) + .08*sin(2.*x + .5) - .08*x; }
float cW(float x, float k){ return (k < .5 ? .48 : .36) + .08*sin(1.2*x + 2.3*k) + .03*sin(2.7*x - k); }
vec3 sheet(vec2 p, float k, vec3 col, out float a, out float dd){
  float x = p.x;
  float y = cY(x, k);
  float w = cW(x, k);
  float e = .01;
  float sl = (cY(x + e, k) - cY(x - e, k))/(2.*e);
  float hem = .012*sin(x*9. + k*3.)*sin(x*3.1 + 1.) + .006*gn(vec2(x*6. + k*3., k));
  float d = (abs(p.y - y) - w)/sqrt(1. + sl*sl) + hem;
  a = 1. - s01(-pxu()*1.2, pxu()*1.2, d);
  dd = d;
  float v = (p.y - y)/w;
  float nf = mix(.5, 1.5, u_opt)*(k > .5 ? .6 : 1.);
  float ph = v*nf*(1. + .6*sin(x*.9 + k*2.)) + .9*sin(x*.8 + k*2.2) + .3*sin(x*1.9 - k) + .35*v*v;
  float s = sin(ph*PI), c = cos(ph*PI);
  float graze = abs(s);
  float dens = .3 + .45*pow(graze, 1.5) + .35*exp(-max(-d, 0.)/.018);
  float sheen = pow(sat(.5 + .5*c), 6.)*(.6 + .4*sin(x*.8 + k));
  vec3 fc = ramp(sat(.08 + .45*k + .2*v + .12*sin(x*.6 + k*1.7)));
  vec3 tr = vec3(mix(col.x, fc.x, mix(.5, .72, dkmF())), mix(col.yz, fc.yz*1.2, .55 + .4*graze));
  tr.x += mix(.04, .12, dkmF())*sheen - mix(.05, -.03, dkmF())*graze*graze;
  tr.x += mix(.02, .06, dkmF())*exp(-max(-d, 0.)/.004);
  a *= sat(dens);
  return tr;
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], mix(u_pal[5], u_pal[0], .16), s01(-1.4, 1.4, p.x - p.y));
  col.x += mix(.012, .05, dkmF())*exp(-dot(p - vec2(-.5, .65), p - vec2(-.5, .65))*.45);
  float a, d;
  vec3 t = sheet(p, 1., col, a, d);
  col = mix(col, t, a);
  float a0, d0;
  t = sheet(p - vec2(.04, -.08), 0., col, a0, d0);
  col = dim(col, mix(.07, .2, dkmF())*(1. - s01(-.1, .08, d0)));
  t = sheet(p, 0., col, a, d);
  col = mix(col, t, a);
  return col;
}

float hV(vec2 p){
  vec2 q = p - vec2(-2.3, -1.55);
  float r = length(q);
  float a = atan(q.y, q.x);
  float u = a*11. + .5*sin(r*1.2 + a*2.) + .2*sin(r*2.7 - a*5.);
  float h = sin(u) + .38*sin(2.03*u + 1.3 + .8*sin(r*2.)) + .12*sin(4.1*u + r);
  return .105*r*h;
}
vec3 wall(vec2 p){
  float e = .0025;
  float h0 = hV(p), hx = hV(p + vec2(e, 0.)), hy = hV(p + vec2(0., e));
  vec2 gr = vec2(hx - h0, hy - h0)/e;
  float cr = u_opt;
  vec2 cn = vec2(gn(p*2.2 + 4.), gn(p*2.2 + 11.)) + .5*vec2(gn(p*5.1), gn(p*5.1 + 3.));
  vec3 n = normalize(vec3(-gr + cr*.14*cn, 1.));
  vec3 L = normalize(vec3(normalize(u_light)*.7, .72));
  float dif = sat(dot(n, L));
  float gz = sat((1. - n.z)*1.7);
  float pch = s01(-.4, .4, fbm3(p*1.1 + 7.));
  float side = .5 + .5*dot(normalize(n.xy + 1e-4), normalize(L.xy));
  float sheen = pow(gz, 2.)*(.25 + .75*side)*(1. + cr*(.8*pch - .3));
  float t = sat(.5 + .32*sin(p.x*.5 - p.y*.4 + .6));
  vec3 base = mix(u_pal[4], u_pal[0], sm1(t));
  vec3 c = vec3(base.x*(.45 + .35*dif), base.yz*1.05);
  vec3 sh = mix(u_pal[1], u_pal[2], sm1(sheen*1.2));
  sh = mix(sh, u_pal[3], .35*sm1(sheen*1.5 - .9));
  c = mix(c, sh, sat(sheen*1.6));
  c.x += .1*pow(sat(sheen*1.2), 3.);
  float hn = hV(p)/(.105*length(p - vec2(-2.3, -1.55)));
  float val = s01(.2, -1.2, hn);
  c = mix(c, vec3(u_pal[5].x, u_pal[5].yz*1.2), .6*val*(1. - sat(sheen*1.5)));
  c.x += .012*gn(p/cssu()*vec2(.8, .3))*(.4 + sheen);
  return c;
}

float tY(float x, float k){ return k < .5 ? -.12 + .3*sin(.7*x + .5) + .08*sin(1.6*x - .6) + .14*x : .5 + .2*sin(.8*x + 2.6) + .06*sin(1.9*x) - .1*x; }
float tTh(float x, float k){ return (k < .5 ? 1. : .8)*mix(.8, 1.45, u_opt)*x + .55*sin(.5*x + 1.1 + k*2.) + .5 + k*1.3; }
vec3 bgT(vec2 p){
  vec3 c = mix(lift(u_pal[5], mix(.025, .07, u_dark)), dim(u_pal[5], mix(.1, .3, u_dark)), sat(.5 - .32*p.y + .12*p.x));
  return c;
}
float ribD(vec2 p, float W, float k){
  float y = tY(p.x, k);
  float hw = W*abs(cos(tTh(p.x, k))) + .0035;
  float e = .01;
  float sl = (tY(p.x + e, k) - tY(p.x - e, k))/(2.*e);
  return (abs(p.y - y) - hw)/sqrt(1. + sl*sl);
}
vec3 ribC(vec2 p, float W, float k, vec3 col){
  float th = tTh(p.x, k);
  float cs = cos(th), sn = sin(th);
  float y = tY(p.x, k);
  float hw = W*abs(cs) + .0035;
  float v = (p.y - y)/hw;
  vec3 n = normalize(vec3(0., -sn, cs));
  if (cs < 0.) n = -n;
  vec3 L = normalize(vec3(normalize(u_light)*.77, .64));
  float dif = sat(dot(n, L));
  vec3 H = normalize(L + vec3(0., 0., 1.));
  float nh = sat(dot(n, H));
  float t = sat(.5 + .26*p.x + .1*v*abs(cs));
  vec3 fr = ramp(t*.5);
  vec3 bk = mix(u_pal[3], u_pal[4], sm1(t));
  vec3 c = cs > 0. ? fr : bk;
  c = vec3(c.x*(.64 + .46*dif), c.yz*(1.05 + .1*(1. - dif)));
  c.x += .14*pow(nh, 26.) + .06*pow(nh, 5.);
  c.x += .006*gn(p/cssu()*.5);
  c.yz *= 1. - .45*pow(nh, 40.);
  c.x += .06*exp(-max(1. - abs(v), 0.)*hw/.004)*(.4 + .6*dif);
  c.x -= .04*exp(-max(1. - abs(v), 0.)*hw/.03)*(1. - dif);
  return c;
}
vec3 wall(vec2 p){
  float W = .3;
  vec3 col = bgT(p);
  float d1 = ribD(p, W*.62, 1.);
  float s1 = ribD(p - vec2(.04, -.09), W*.62, 1.);
  col = dim(col, mix(.16, .3, u_dark)*(1. - s01(-.08, .12, s1)));
  vec3 c1 = ribC(p, W*.62, 1., col);
  c1 = mix(c1, dim(u_pal[5], .1), mix(.32, .38, u_dark));
  float fw1 = pxu()*1.5 + .006*s01(.2, 1.4, abs(p.x - .2));
  col = mix(col, c1, 1. - s01(-fw1, fw1, d1));
  float s0 = ribD(p - vec2(.07, -.17), W, 0.);
  col = dim(col, mix(.2, .38, u_dark)*(1. - s01(-.12, .22, s0)) + mix(.06, .1, u_dark)*(1. - s01(-.02, .05, ribD(p - vec2(.02, -.05), W, 0.))));
  float fw0 = pxu()*1.5 + .005*s01(.2, 1.4, abs(p.x + .1));
  col = mix(col, ribC(p, W, 0., col), 1. - s01(-fw0, fw0, ribD(p, W, 0.)));
  return col;
}

vec2 swirlS(vec2 p, vec2 c, float s, float r){
  vec2 d = p - c;
  float a = s*exp(-dot(d, d)/(r*r));
  return c + rot(a)*d;
}
vec3 bgS(vec2 p){
  vec3 c = mix(lift(u_pal[5], mix(.02, .05, u_dark)), dim(u_pal[5], mix(.1, .35, u_dark)), sat(.5 + .25*p.x - .3*p.y));
  vec2 b = p - vec2(-1.15, -.55);
  c = mix(c, mix(c, u_pal[1], .4), .5*exp(-dot(b, b)*2.2));
  vec2 b2 = p - vec2(-.35, .85);
  c = mix(c, mix(c, u_pal[0], .35), .45*exp(-dot(b2, b2)*3.));
  return c;
}
vec3 wall(vec2 p){
  vec3 col = bgS(p);
  vec2 C = vec2(.78, .02);
  float R = .8;
  vec2 q = (p - C)/R;
  float r = length(q);
  vec3 sh = col;
  if (r < 1.06) {
    float z = sqrt(max(1. - r*r, 0.));
    float sw = mix(.5, 2.4, u_opt);
    vec2 s = q*(1. + .35*(1. - z));
    s = swirlS(s, vec2(.45, .2), sw, .3);
    s = swirlS(s, vec2(-.45, -.3), -sw*.8, .32);
    s = swirlS(s, vec2(.15, -.62), sw*.7, .25);
    s = swirlS(s, vec2(-.2, .35), -sw*.5, .22);
    s += .22*vec2(fbm3(s*1.7 + 3.), fbm3(s*1.7 + 8.));
    float T = .55 - .45*s.y + .1*fbm3(s*vec2(1.8, 3.) + 1.);
    T = max(T, 0.);
    float ph = pow(T, 1.45)*7.5;
    float tri = abs(fract(ph*.5) - .5)*2.;
    vec3 fc = ramp(tri);
    float thin = s01(.03, .2, T);
    fc.yz *= .6 + .55*exp(-T*.8);
    fc.x += .04*cos(ph*PI*2.);
    float F = .08 + .92*pow(1. - z, 2.);
    float rf = F*thin;
    float addL = .85*fc.x*rf;
    vec3 thD = vec3(col.x + addL, col.yz + fc.yz*1.35*addL/max(fc.x, .3));
    float rfl = pow(F, 1.6)*thin;
    vec3 thL = vec3(col.x - .015*rfl + .01*(1. - z), mix(col.yz, fc.yz*1.05, sat(rfl*1.5)));
    thL.x = mix(thL.x, fc.x, .25*rfl);
    vec3 th = mix(thL, thD, u_dark);
    vec2 wq = q*(1. + .35*z);
    vec2 wc = wq - vec2(-.42, .44);
    wc.x *= 1. + .5*wc.y;
    wc *= vec2(.85, 1.);
    float arch = length(vec2(wc.x, max(wc.y - .05, 0.))) - .13;
    float wsh = max(max(abs(wc.x) - .13, -.17 - wc.y), wc.y > .05 ? arch : -1.);
    float win = (1. - s01(-.01, .01, wsh))*(.45 + .55*s01(-.17, .18, wc.y))*(1. - .25*exp(-abs(wc.x)/.006));
    float bloom = exp(-max(wsh, 0.)/.03)*.25;
    float wb2 = sdBox(wq - vec2(.5, -.55), vec2(.06, .035), .02);
    win += .35*(1. - s01(-.01, .01, wb2));
    th.x += mix(.2, .34, u_dark)*win + mix(.03, .06, u_dark)*bloom;
    th.yz *= 1. - .8*sat(win);
    float rim = exp(-(1. - r)/.012)*(r < 1. ? 1. : 0.);
    th.x += mix(.06, .14, u_dark)*rim;
    th.x -= .07*(1. - u_dark)*exp(-abs(r - .985)/.012);
    col = mix(col, th, cover((r - 1.)*R));
  }
  vec2 g = (p - C - vec2(.08, -R - .02))/vec2(R*.9, .06);
  col.x += mix(.015, .04, u_dark)*exp(-dot(g, g))*s01(1.06, .8, r);
  return col;
}

float starN(vec2 p, float s, float dens, float sz){
  vec2 cell = floor(p/s);
  vec2 sp = (cell + .15 + .7*h22(cell))*s;
  float on = step(dens, h21(cell + 9.7));
  float r = max(sz*(.5 + 1.2*h21(cell + 3.1)), cssu()*.5);
  float d = length(p - sp);
  return on*(exp(-d*d/(r*r)) + .08*exp(-d/(r*5.)));
}
vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], .015), dim(u_pal[5], .25), sat(.5 + .3*p.y - .2*p.x));
  col = mix(col, mix(col, u_pal[1], .25), (1. - u_dark)*sat(.6 - .3*p.y));
  vec2 q = rot(.42)*p;
  vec2 w = q + .55*vec2(fbm(q*.9 + 1.), fbm(q*.9 + 7.));
  vec2 w2 = w + .18*vec2(fbm3(w*1.8 + 4.), fbm3(w*1.8 + 9.));
  float band = exp(-pow((w.y + .12 + .18*sin(w.x*.8 + 1.))/.55, 2.));
  float f1 = fbm(w2*1.2 + 3.);
  float dens = band*s01(-.8, .9, f1 + .25*band)*.8 + .2*band*band;
  float wisp = pow(1. - abs(gn(w2*3.2 + 2.)), 4.)*band*.6;
  dens = sat(dens + wisp*.5);
  vec2 hc = vec2(.95, .32);
  float hr = length(p - hc);
  float core = exp(-hr*2.6);
  float tc = sat(.42 + 1.1*fbm(w*.7 + 5.) - .25*(p.x - hc.x) + .3*core);
  vec3 gas = ramp(tc);
  float ridge = 1. - abs(gn(w2*2.4 + 11.) + .3*gn(w2*5.3));
  float dust = s01(.55, .92, ridge)*s01(.1, .7, band)*mix(.2, 1., u_opt);
  dust = sat(dust + .45*u_opt*s01(.2, .6, fbm3(w2*1.2 + 20.))*band);
  float em = dens*(1. - .85*dust);
  vec3 dk = vec3(col.x + mix(.6, 1., u_dark)*(.75*gas.x*em*em + .2*gas.x*em), col.yz + gas.yz*1.15*sat(em*1.6));
  dk.x += .35*core*core*(1. - .5*dust) + .1*core;
  vec3 lt = vec3(mix(col.x, gas.x - .08, sat(em*1.3)*.75), mix(col.yz, gas.yz*1.3, sat(em*1.8 + .1)));
  lt.x += .06*core;
  lt = mix(lt, dim(lt, .35), dust*dens*.6);
  col = mix(mix(dk, lt, .25), dk, u_dark);
  float st = starN(p, .05, .82, .0012) + .6*starN(p + 3.1, .021, .7, .0008) + 1.5*starN(p + 7.7, .19, .86, .0024);
  col.x += .7*st*(1. - .8*dust*dens)*mix(.35, 1., u_dark);
  col.x += .5*exp(-hr*hr/.0004)*u_dark + .2*exp(-hr/.04);
  return col;
}

vec3 wall(vec2 p){
  vec2 C = vec2(-.35, -4.35);
  float R = 3.72;
  vec2 v = p - C;
  float r = length(v);
  float d = r - R;
  vec2 dir = v/r;
  float ang = atan(dir.x, dir.y);
  float sa = .3;
  float da = ang - sa;
  vec2 S = C + R*vec2(sin(sa), cos(sa));
  float ds = length(p - S);
  vec3 space = mix(u_pal[5], mix(dim(u_pal[5], .22), mix(u_pal[5], u_pal[3], .35), 1. - u_dark), sat(p.y*.5 + .3));
  space = mix(space, mix(u_pal[5], u_pal[0], mix(.25, .2, u_dark)), sat(.35*exp(-max(d, 0.)*2.2)));
  vec2 cell = floor(p/.04);
  vec2 sp = (cell + .2 + .6*h22(cell))*.04;
  float sz = max(.0011, cssu()*.45)*(.6 + 1.1*h21(cell + 3.1));
  float on = step(.8, h21(cell + 9.7));
  space.x += .45*on*exp(-dot(p - sp, p - sp)/(sz*sz))*u_dark*s01(.05, .5, d);
  float k = mix(.6, 1.3, u_opt);
  float warm = exp(-da*da*9.);
  vec3 airC = mix(u_pal[1], u_pal[2], warm);
  float thin = exp(-abs(d)/.012)*(d > 0. ? 1. : .4);
  float glow = exp(-max(d, 0.)/(.07 + .05*k))*(d > 0. ? 1. : 0.);
  float haze = exp(-max(d, 0.)/.32)*(d > 0. ? 1. : 0.);
  float side = exp(-da*da*1.2);
  vec3 col = space;
  col = mix(col, airC, sat(haze*.35*k*side));
  col = mix(col, lift(airC, .05), sat(glow*.85*k*(.4 + .6*side)));
  col.x += thin*.25*k*(.3 + .7*side);
  if (d < 0.) {
    float dep = -d;
    vec2 g = vec2(ang*R, dep*(6. + 30.*dep));
    float cl = s01(-.1, .5, fbm(g*vec2(3.2, 1.6) + 2.));
    float lit = s01(-.9, .25, -da*1.2 + .2) ;
    vec3 surf = mix(u_pal[3], dim(u_pal[3], .5), s01(.0, .6, dep));
    surf = mix(surf, mix(u_pal[2], lift(u_pal[3], .25), .5), cl*mix(.35, .55, 1. - u_dark)*lit*exp(-dep*1.5));
    surf.x += .12*lit*exp(-dep/.05)*side;
    surf = mix(surf, airC, .5*exp(-dep/.035)*(.4 + .6*side));
    col = mix(col, surf, cover(d));
  }
  float sun = exp(-ds*ds/.0009);
  col.x += .55*sun + .22*exp(-ds/.06) + .1*exp(-ds/.3);
  col.yz = mix(col.yz, u_pal[4].yz, sat(sun + .5*exp(-ds/.06)));
  float streak = exp(-abs(p.y - S.y)/.004)*exp(-abs(p.x - S.x)/.6);
  col.x += .12*streak*(.5 + .5*u_dark);
  return col;
}

float hCS(vec2 q, float t, float bl){
  float lod = exp(-t*.05);
  vec2 w = q*.42 + .35*vec2(gn(q*.11 + 3.), gn(q*.11 + 9.));
  float h = .5*abs(gn(w)) + .3*abs(gn(rot(.7)*w*2.1 + 4.3));
  h += lod*(.2*abs(gn(rot(1.4)*w*4.4 + 1.7)) + .11*abs(gn(rot(2.1)*w*9.1 + 7.1)) );
  h += .2*gn(q*.07 + 5.);
  return .34*bl*h;
}
vec3 skyCS(vec3 d, vec3 S){
  float t = sat(d.y*1.6);
  vec3 sky = mix(u_pal[0], u_pal[1], sm1(t*2.2));
  sky = mix(sky, u_pal[2], sm1(t*1.6 - .45));
  sky = mix(sky, u_pal[5], sm1(t*1.3 - .7));
  float cs = max(dot(d, S), 0.);
  sky = mix(sky, u_pal[4], .5*pow(cs, 12.) + .35*pow(cs, 90.));
  return sky;
}
vec3 wall(vec2 p){
  float bl = mix(.7, 1.3, u_opt);
  vec3 S = normalize(vec3(-.78, .09, 1.));
  vec3 d = normalize(vec3(p.x, p.y - .12, 1.7));
  vec3 col = skyCS(d, S);
  vec2 Sp = S.xy/S.z*1.7 + vec2(0., .12);
  float sd = length(p - Sp);
  col = mix(col, lift(u_pal[4], .04), 1. - s01(.05, .058, sd));
  col.x += .2*exp(-sd/.04);
  if (d.y < .01) {
    vec3 ro = vec3(0., 1., 0.);
    float top = .5*bl;
    float dy = max(-d.y, .004);
    float t = (ro.y - top)/dy;
    float tp = t;
    float hit = 0.;
    for (int i = 0; i < 44; i++) {
      if (hit < .5 && t < 90.) {
        vec3 q = ro + d*t;
        float gap = q.y - hCS(q.xz, t, bl);
        if (gap < 0.) { hit = 1.; } else { tp = t; t += clamp(gap*.75/dy, .01*t + .012, 4.); }
      }
    }
    float ta = tp, tb = t;
    for (int j = 0; j < 5; j++) {
      float tm = .5*(ta + tb);
      vec3 q = ro + d*tm;
      if (q.y < hCS(q.xz, tm, bl)) tb = tm; else ta = tm;
    }
    t = tb;
    vec3 P = ro + d*t;
    float e = .06 + .004*t;
    float h0 = hCS(P.xz, t, bl);
    float hx = hCS(P.xz + vec2(e, 0.), t, bl), hz = hCS(P.xz + vec2(0., e), t, bl);
    vec3 n = normalize(vec3(-(hx - h0)/e, 1., -(hz - h0)/e));
    float dif = sat(dot(n, normalize(vec3(S.x, .35, S.z*.6)))*.55 + .5);
    float ht = sat(h0/(.48*bl));
    float back = pow(max(dot(d, S), 0.), 4.);
    float graze = pow(1. - sat(dot(n, -d)), 2.);
    float lum = sat(.12 + .6*ht + .55*(dif - .5) + .15*back);
    vec3 c = mix(u_pal[2], u_pal[1], sm1(lum*1.6));
    c = mix(c, u_pal[0], sm1(lum*1.5 - .55));
    c = mix(c, u_pal[4], sm1(lum*1.4 - .9)*.7);
    c = mix(c, u_pal[4], sat(graze*back*1.6)*.6);
    c = mix(c, u_pal[3], sat(.55 - ht*1.3)*.5);
    c.x += .02*fbm3(P.xz*4.)*exp(-t*.1);
    vec3 hzc = skyCS(vec3(d.x, .0, d.z), S);
    float fog = 1. - exp(-t*.055);
    c = mix(c, hzc, fog*.92);
    c = mix(c, hzc, s01(.0, -.02, -d.y - .002)*0.);
    col = mix(col, c, hit*s01(.004, -.002, d.y));
    col = mix(col, hzc, (1. - hit)*s01(.004, -.002, d.y));
  }
  return col;
}

float dkmF(){ return 1. - s01(.3, .7, u_pal[5].x); }
vec3 wall(vec2 p){
  vec2 O = vec2(1.02, -.5);
  vec3 bg = mix(u_pal[5], dim(u_pal[5], mix(.08, .3, dkmF())), sat(length(p - vec2(-1.2, .8))*.4));
  bg = mix(bg, mix(bg, u_pal[0], .35), exp(-length(p - O)*1.3)*mix(.5, 1., dkmF()));
  float Ls = 0., ws = 0.;
  vec2 ab = vec2(0.);
  float g = mix(.6, 1.3, u_opt);
  for (int k = 0; k < 16; k++) {
    float i = float(k);
    float ring = i < 9. ? 0. : 1.;
    float j = ring < .5 ? i : i - 9.;
    float n = ring < .5 ? 9. : 7.;
    float th = j/n*2.*PI + ring*.35 + .2;
    vec2 q = rot(-th)*(p - O);
    float Lp = ring < .5 ? 1.25 : .78;
    q.y -= .07*q.x*q.x*(ring < .5 ? 1. : -1.);
    float s = q.x/Lp;
    float w = (ring < .5 ? .3 : .24)*pow(sat(sin(PI*sat(s))), .75)*(1. - .25*s);
    float d = abs(q.y) - w;
    float inside = 1. - s01(-.004, .004, max(d, max(-q.x, q.x - Lp)));
    float rimd = max(w - abs(q.y), 0.);
    float rim = exp(-rimd/.012) + .35*exp(-rimd/.06);
    float vein = exp(-abs(q.y)/.004)*s01(.0, .3, s)*s01(1., .5, s)*.4;
    float I = inside*(.12 + .55*rim + vein)*(.6 + .4*s01(1., .2, s));
    vec3 c = ramp(sat(ring*.45 + .5*s + .08*sin(i*2.3)));
    Ls += I*c.x;
    ab += I*c.yz;
    ws += I;
  }
  vec2 hue = ab/max(ws, 1e-3);
  float E = 1. - exp(-ws*g*1.1);
  vec3 dk = vec3(bg.x + .78*E*(Ls/max(ws, 1e-3)), mix(bg.yz, hue*1.15, sat(E*1.6)));
  dk.yz *= 1. - .35*s01(.6, 1., E);
  vec3 lt = vec3(bg.x - .12*E + .1*s01(.5, 1., E), mix(bg.yz, hue*1.25, sat(E*1.5)));
  vec3 col = mix(lt, dk, dkmF());
  float cr = length(p - O);
  col.x += mix(.1, .4, dkmF())*exp(-cr/.05)*g;
  col.yz *= 1. - .4*exp(-cr/.04);
  return col;
}

float edgeP(float a, float k){ return (k < .5 ? 3.25 : 2.45) + .1*sin(a*7. + k*2.) + .05*sin(a*15. + 1. + k) + .025*sin(a*31. + k*4.); }
vec3 petal(vec2 p, vec2 B, float k, vec3 col){
  vec2 v = p - B;
  float r = length(v), a = atan(v.y, v.x);
  float er = edgeP(a, k);
  float d = r - er;
  float s = r/er;
  float cr = fbm3(vec2(a*9., r*2.2) + k*5.);
  float crk = .5 + .5*sin(a*46. + 2.5*cr + r*1.5);
  float vein = pow(.5 + .5*sin(a*150. + 3.*fbm3(vec2(a*6., r*1.4) + 3.) + k*3.), 6.);
  float bl = mix(.6, 1.3, u_opt);
  vec3 c = ramp(sat(.1 + .75*s*s + .1*cr - .25*(1. - k)));
  c = mix(u_pal[4], c, s01(.0, .55, s));
  c.x += (.04*crk - .02 + .06*cr)*(.5 + .5*s);
  c.x -= .025*vein*s01(.2, .9, s);
  c.yz *= 1. + .12*vein;
  float rim = exp(-max(-d, 0.)/.012);
  c.x += bl*(.14*rim + .08*exp(-max(-d, 0.)/.08))*s01(.5, 1., s);
  c.yz *= 1. - .25*rim;
  c = mix(c, dim(c, .55), (1. - bl*.6)*s01(.6, .0, s)*.6);
  float sh = 1. - s01(-.25, .05, d - .1);
  c = mix(c, col, 0.);
  return mix(dim(col, .4*sh*(1. - u_dark*.2)), c, cover(d));
}
vec3 wall(vec2 p){
  vec3 bg = mix(u_pal[5], dim(u_pal[5], .25), sat(.5 - .3*p.x + .2*p.y));
  vec2 b1 = p - vec2(-.8, .7);
  bg = mix(bg, mix(bg, u_pal[2], .5), .6*exp(-dot(b1, b1)*3.));
  vec2 b2 = p - vec2(.3, .95);
  bg = mix(bg, mix(bg, u_pal[3], .45), .5*exp(-dot(b2, b2)*6.));
  vec3 col = bg;
  col = petal(p, vec2(-.2, -2.5), 0., col);
  col = petal(p, vec2(-1.75, -1.45), 1., col);
  return col;
}

vec3 wall(vec2 p){
  vec3 bg = mix(lift(u_pal[5], mix(.02, .05, u_dark)), dim(u_pal[5], mix(.1, .32, u_dark)), sat(.5 - .3*p.y + .2*p.x));
  vec2 C = vec2(1.0, -.12);
  vec2 v = rot(2.75)*(p - C);
  float r = length(v);
  float ph = atan(v.y, v.x);
  float b = .19;
  float s = log(max(r, 1e-4)/.012)/b;
  float u = (s - ph)/(2.*PI);
  float n = floor(u), f = u - n;
  float N = 4.;
  float Th = ph + 2.*PI*n;
  float shellD = (u - N)*2.*PI*b*r;
  vec3 col = bg;
  float sh = 1. - s01(-.02, .2, (u - N - .05)*2.*PI*b*length(rot(2.75)*(p - C - vec2(.05, -.08))));
  col = dim(col, mix(.08, .45, u_dark)*sh*s01(.0, .08, -shellD + .1));
  if (u < N + .02) {
    float D = mix(.42, .55, sat(n/N));
    float sp = Th + .55*sin(PI*f) + .25*f;
    float ci = floor(sp/D);
    float cf = sp/D - ci;
    float wallT = .07;
    float wlw = min(f, 1. - f);
    float septd = min(cf, 1. - cf)*D*r*.9;
    float nac = mix(.5, 1.2, u_opt);
    float t = sat(.15 + .65*sm1(sat(s/(2.*PI*N))) + .08*sin(ci*1.7));
    vec3 c = ramp(t);
    c = vec3(c.x*(.62 + .38*cf + .1*sin(f*PI)), c.yz);
    float ir = sin(ph*2. + f*3. + ci*.9)*.5 + .5;
    c.yz = mix(c.yz, rot(ir*1. - .5)*c.yz*1.15, .5*nac);
    c.x += .05*nac*pow(ir, 3.);
    float sept = exp(-septd/(.004 + .006*r));
    vec3 pearl = mix(u_pal[4], u_pal[3], .4 + .3*sin(ph + ci));
    c = mix(c, pearl, sat(sept*1.2));
    c.x -= .08*exp(-septd/(.03*r + .01))*(1. - sept);
    float wd = wlw*2.*PI*b*r;
    float wl2 = exp(-wd/(.006 + .012*r));
    c = mix(c, mix(pearl, u_pal[4], .5), sat(wl2*1.1));
    c.x -= .06*exp(-wd/(.04*r + .01))*(1. - wl2);
    float outS = s01(-.006, .002, shellD);
    float lip = exp(-max(-shellD, 0.)/.02);
    c = mix(c, lift(pearl, .03), lip*.8);
    col = mix(c, col, outS);
  }
  vec2 sb = (p - vec2(-.3, .7))/vec2(1.4, .6);
  col.x += .03*exp(-dot(sb, sb))*(1. - u_dark*.5);
  return col;
}

float flowP(vec2 p, out vec2 b){
  vec2 q = rot(.45)*p;
  vec2 a = vec2(fbm3(q*.55 + vec2(0., 0.)), fbm3(q*.55 + vec2(5.2, 1.3)));
  b = vec2(fbm3(q*.8 + 1.6*a + vec2(1.7, 9.2)), fbm3(q*.8 + 1.6*a + vec2(8.3, 2.8)));
  float sw = mix(.45, 1., u_opt);
  return q.y*.8 + sw*(.9*a.x + .55*b.y);
}
vec3 wall(vec2 p){
  vec2 b, b1, b2;
  float f = flowP(p, b);
  float e = .003;
  float fx = flowP(p + vec2(e, 0.), b1), fy = flowP(p + vec2(0., e), b2);
  float gl = length(vec2(fx - f, fy - f))/e;
  float t = f*24. + 2.5*sin(f*4.1) + 1.2*sin(f*9.7);
  float id = floor(t);
  float fr = t - id;
  float ed = min(fr, 1. - fr)/(24.*max(gl, 1e-3));
  float h = h21(vec2(id, 3.1));
  float ground = step(.45, h21(vec2(id, 7.7)));
  vec3 pc = ramp(floor(h*4.99)/4.);
  vec3 col = mix(pc, u_pal[5], ground);
  vec3 nb = mix(ramp(floor(h21(vec2(id + 1., 3.1))*4.99)/4.), u_pal[5], step(.45, h21(vec2(id + 1., 7.7))));
  float aa = s01(-pxu(), pxu(), ed - .0015);
  float lace = exp(-ed/.004)*.5;
  vec3 col0 = col;
  col = mix(mix(col, nb, .5), col, aa);
  col.x -= .06*lace*(1. - ground);
  float cellBand = step(.8, h21(vec2(id, 11.)));
  vec2 cq = p*16. + b*8.;
  vec2 ci = floor(cq), cf = cq - ci;
  float md = 9.;
  for (int j = -1; j < 2; j++) for (int i = -1; i < 2; i++) {
    vec2 o = vec2(float(i), float(j));
    vec2 r = o + h22(ci + o)*.8 + .1 - cf;
    md = min(md, dot(r, r));
  }
  float cell = s01(.16, .08, md)*s01(.0, .04, ed)*cellBand;
  vec3 cc = mix(ramp(fract(h + .4)), u_pal[5], .35*(1. - ground));
  col = mix(col, cc, cell);
  col.x -= .08*cellBand*s01(.2, .14, md)*s01(.08, .16, md)*s01(.0, .04, ed);
  float dif = s01(.0, .05, length(col - nb));
  float rel = exp(-ed/.012)*dif;
  vec2 sb = (p - vec2(-.6, .55))/vec2(1.1, .5);
  float soft = exp(-pow(dot(sb, sb), 1.5));
  col.x += mix(.05, .09, u_dark)*soft*(.6 + .4*rel) + .03*rel*s01(-.5, .8, p.y - p.x*.3);
  col.yz *= 1. - .15*soft;
  return col;
}

float archD(vec2 l){
  float w = .5, yb = -1.05, yc = .05;
  vec2 a = vec2(abs(l.x), l.y);
  float body = max(a.x - w, yb - l.y);
  float top = length(vec2(a.x, l.y - yc)) - w;
  return l.y > yc ? top : body;
}
vec3 wall(vec2 p){
  vec2 V = vec2(-1.36, -.08);
  float k0 = .72;
  vec2 sun = vec2(.22, -.12)*mix(.6, 1.4, u_opt);
  vec3 col = lift(u_pal[4], .02);
  float done = 0.;
  for (int k = 0; k < 11; k++) {
    float i = float(k);
    float s = pow(k0, i - 1.);
    vec2 l = (p - V)/s;
    float dOuter = i < .5 ? -1. : archD(l);
    float sN = s*k0;
    vec2 lN = (p - V)/sN;
    float dIn = archD(lN);
    float thick = .9;
    vec2 lT = (p - V)/(sN*thick);
    float dT = archD(lT);
    float onWall = (1. - done)*cover(dOuter*s)*(1. - cover(dIn*sN));
    float onRev = (1. - done)*cover(dIn*sN)*(1. - cover(dT*sN*thick));
    if (onWall + onRev > 0.) {
      float u = sat(i/9.);
      vec3 base = ramp(u*.75);
      base = mix(base, u_pal[3], .25*mod(i, 2.));
      vec2 lp = (p - V - sun*s)/s;
      float lit = cover(archD(lp)*s - .004);
      if (i < .5) lit = .3 + .7*s01(.1, -.1, p.x*.55 - p.y + .55 + .08*sin(p.y*3.))*s01(1.7, .9, p.x);
      vec3 shade = vec3(base.x*.68, base.yz*1.08);
      vec3 wc = mix(shade, vec3(base.x*1.08 + .04, base.yz*.95), lit);
      wc = mix(wc, u_pal[4], .18*u);
      wc.x += .012*fbm3(p*vec2(9., 7.)/s);
      vec2 rl = lN;
      float side = rl.x;
      float isFloor = s01(-.97, -1.02, rl.y);
      vec3 rc = mix(vec3(base.x*.82, base.yz), vec3(base.x*1.12, base.yz*.9), s01(.0, .3, -side));
      rc = mix(rc, vec3(base.x*.6, base.yz*1.05), s01(.1, .3, rl.y - .05)*.6);
      rc = mix(rc, mix(u_pal[4], base, .55), isFloor);
      col = mix(col, wc, onWall);
      col = mix(col, rc, onRev);
      done = sat(done + onWall + onRev);
    }
  }
  float gr = length((p - V - vec2(0., -.3))*vec2(1., .8));
  col.x += .05*exp(-gr*2.5)*(1. - done*.8);
  return col;
}

float cwE(float y, float i, float sd){
  return .22*sin(y*(1.3 + .25*i) + i*2.1 + sd) + .11*sin(y*(2.9 + .3*i) - i*1.3 + sd*2.) + .04*gn(vec2(y*3.5 + i*5., sd));
}
vec3 wall(vec2 p){
  vec2 G = vec2(.42, 0.);
  float gl = mix(.6, 1.35, u_opt);
  vec3 sky = mix(u_pal[4], lift(u_pal[3], .05), s01(.9, -.2, p.y));
  vec3 col = sky;
  float done = 0.;
  for (int k = 0; k < 9; k++) {
    float i = float(k);
    float u = i/8.;
    float side = mod(i, 2.) < .5 ? -1. : 1.;
    float gap = .025 + 1.05*pow(u, 1.6);
    float off = G.x + .1*sin(p.y*.8 + i)*(1. - u) + .05*u*side;
    float e = side*(p.x - off) - gap - cwE(p.y, i, side*3.)*(.35 + .9*u);
    float e2 = side*(p.x + .004 - off) - gap - cwE(p.y, i, side*3.)*(.35 + .9*u);
    float a = cover(-e*(1. + .3*u));
    if (a > 0.) {
      float dep = max(e, 0.);
      vec3 c = ramp(sat(.92 - .95*u + .1*sin(p.y*2. + i)));
      float rim = exp(-dep/(.008 + .02*u));
      float glow = exp(-dep/(.08 + .1*u))*gl;
      c = mix(mix(c, u_pal[0], .55), c, .35 + .65*sat(glow));
      c = mix(c, mix(u_pal[3], u_pal[4], .4), rim*.42*gl);
      float str = .5 + .5*sin((p.y*9. - cwE(p.y, i, side*3.)*6. + side*dep*4.)*2. + i);
      c.x += .025*str*(1. - rim) - .012;
      c = mix(c, mix(u_pal[0], u_pal[5], .5), s01(.05, .9, dep)*u*.7);
      col = mix(col, c, a);
    }
  }
  float beam = exp(-pow((p.x - G.x - .05*p.y)/.06, 2.))*s01(-1., 1., p.y);
  col.x += .08*beam*gl;
  col.yz *= 1. - .2*beam;
  return col;
}

float dkmF(){ return 1. - s01(.3, .7, u_pal[5].x); }
vec3 wall(vec2 p){
  vec3 bg = mix(u_pal[5], dim(u_pal[5], mix(.04, .3, dkmF())), sat(.5 - .3*p.y + .15*p.x));
  float bl = mix(.6, 1.4, u_opt);
  vec2 q = rot(-.35)*p;
  vec2 w = q + .55*bl*vec2(fbm3(q*.7 + 1.), fbm3(q*.7 + 6.));
  w += .18*bl*vec2(fbm3(w*1.9 + 3.), fbm3(w*1.9 + 9.));
  vec2 wp = rot(.35)*w;
  float env = exp(-pow((wp.y + .5 - .28*wp.x - .14*wp.x*wp.x + .12*sin(wp.x*1.7))/(.32 + .12*sat(wp.x + .5)), 2.))*s01(-2.1, -.9, wp.x);
  float body = s01(-.35, .55, fbm(w*.85 + 2.));
  float sh = 0., a = .7, f = 1.5;
  vec2 ww = w;
  for (int o = 0; o < 3; o++) {
    float fo = float(o);
    ww = rot(.9)*ww;
    sh += a*pow(1. - abs(gn(ww*f + fo*3.17 + vec2(.37, fo*.71))), 7.);
    a *= .5; f *= 2.1;
  }
  float D = sat(env*(.45*body + .8*sh*(.4 + .8*body)));
  float t = sat(.5 + .35*w.x + .3*fbm3(w*.6 + 8.));
  vec3 ic = ramp(t);
  vec3 lt = vec3(mix(bg.x, ic.x - .1, sat(D*1.25)), mix(bg.yz, ic.yz*1.2, sat(D*1.9)));
  vec3 dk = vec3(bg.x + 1.1*ic.x*(1. - exp(-D*2.1)), bg.yz + ic.yz*1.15*sat(D*2.1));
  return mix(lt, dk, dkmF());
}

float agD(vec2 p){
  vec2 C = vec2(1.1, -.55);
  vec2 q = p - C;
  q += .2*vec2(fbm3(p*.9 + 2.), fbm3(p*.9 + 7.));
  float a = atan(q.y, q.x);
  float r = length(q*vec2(1., 1.2));
  return r*(1. + .1*sin(a*3. + 1.) + .05*sin(a*5. + 2.)) + .025*fbm3(p*4.);
}
vec3 wall(vec2 p){
  float d = agD(p);
  float K = mix(18., 30., u_opt);
  float t = d*K;
  float grp = .5 + .5*sin(d*5.3 + 1.3*fbm3(p*.7 + 9.));
  float fine = pow(.5 + .5*sin(t*2.*PI), 3.);
  float fine2 = pow(.5 + .5*sin(t*2.*PI*2.3 + 1.), 6.);
  float lines = s01(.3, 1., grp)*(.7*fine + .5*fine2);
  float wide = s01(.55, .1, grp);
  vec3 base = ramp(sat(.95 - d*.62 + .1*sin(d*3.1)));
  vec3 col = base;
  col = mix(col, mix(u_pal[4], base, .3), sat(lines)*.7);
  col = mix(col, dim(base, .25), wide*.45);
  col.x += .06*wide*(.5 + .5*sin(d*9.));
  float rind = s01(1.62, 1.8, d + .05*fbm3(p*2.));
  col = mix(col, mix(u_pal[5], u_pal[0], .25), rind*.9);
  float core = s01(.42, .22, d);
  vec3 qz = mix(u_pal[4], u_pal[3], .35);
  qz.x += .05*sin(d*60.)*core;
  col = mix(col, qz, core*.85);
  col.x += .08*exp(-pow((d - .4)/.03, 2.));
  vec2 sb = (p - vec2(-.6, .55))/vec2(1.3, .55);
  float soft = exp(-dot(sb, sb));
  col.x += .06*soft;
  col.yz *= 1. - .12*soft;
  return col;
}

float trY(float x, float b){ return b < .5 ? -.38 + .52*sin(.62*x - .15) + .06*sin(1.7*x + .3) : .42 + .16*sin(.95*x + 2.2) - .22*x + .04*sin(2.1*x); }
vec3 wall(vec2 p){
  vec3 bg = mix(lift(u_pal[5], mix(.02, .04, u_dark)), dim(u_pal[5], mix(.08, .3, u_dark)), sat(.5 + .3*p.y - .1*p.x));
  float ex = mix(.6, 1.4, u_opt);
  float Ls = 0., ws = 0.;
  vec2 ab = vec2(0.);
  for (int bi = 0; bi < 2; bi++) {
    float b = float(bi);
    float e = .01;
    float y0 = trY(p.x, b);
    float sl = (trY(p.x + e, b) - trY(p.x - e, b))/(2.*e);
    float nrm = 1./sqrt(1. + sl*sl);
    float spread = (b < .5 ? 1. : .7)*(.01 + .03*sat((p.x + 1.7)/3.4) + .006*sin(p.x*1.3 + b*2.));
    for (int k = 0; k < 8; k++) {
      float i = float(k);
      float off = (i - 3.5)*spread + .006*sin(p.x*3.1 + i*1.7 + b*4.);
      float d = abs(p.y - y0 - off)*nrm;
      float wdt = .0016 + .0011*h21(vec2(i, b + 3.)) + pxu()*.35;
      float tap = b < .5 ? s01(-2.1 + .1*i, -1.5 + .05*i, p.x) : s01(1.9 - .1*i, 1.2 - .05*i, p.x)*s01(-1.9, -1.1 + .08*i, p.x);
      float core = exp(-d*d/(wdt*wdt));
      float glow = exp(-d/.016)*.32 + exp(-d/.08)*.07;
      float I = (core + glow)*tap*(.6 + .4*h21(vec2(i*1.3, b)))*(1. + .08*sin(p.x*40. + i*7.)*0.);
      vec3 c = ramp(fract(b*.55 + i*.09 + .04*p.x));
      Ls += I*c.x*(1. + .5*core);
      ab += I*c.yz*(1. - .55*core);
      ws += I;
    }
  }
  vec2 hue = ab/max(ws, 1e-3);
  float E = 1. - exp(-ws*ex*.9);
  float hot = s01(.75, 1.4, ws*ex*.6);
  vec3 dk = vec3(bg.x + E*mix(.6, .98, hot), mix(bg.yz, hue*1.2, sat(E*1.5))*(1. - .7*hot));
  vec3 lt = vec3(mix(bg.x, .68 + .3*hot, sat(E*1.1)), mix(bg.yz, hue*1.35, sat(E*1.6))*(1. - .55*hot));
  return mix(lt, dk, u_dark);
}

vec3 wall(vec2 p){
  vec3 bg = mix(lift(u_pal[5], mix(.025, .06, u_dark)), dim(u_pal[5], mix(.1, .32, u_dark)), sat(.5 - .3*p.y + .15*p.x));
  vec2 A = normalize(vec2(1., -.3));
  vec2 N = vec2(-A.y, A.x);
  vec2 O = vec2(.35, -.6);
  float om = mix(9., 13., u_opt);
  float R = .3, r = .085;
  vec2 v = p - O;
  float u = dot(v, A), w = dot(v, N);
  float P = 2.*PI/om;
  float kt = .95;
  float b1 = 9., b2 = 9., t1 = 0., t2 = 0.;
  float sep = .3*P;
  for (int k = 0; k < 96; k++) {
    float t = u + (float(k)/95. - .5)*P*1.8;
    vec2 dv = vec2(u, w) - vec2(t + kt*R*sin(om*t), R*cos(om*t));
    float dd = dot(dv, dv);
    if (dd < b1) {
      if (abs(t - t1) > sep) { b2 = b1; t2 = t1; }
      b1 = dd; t1 = t;
    } else if (dd < b2 && abs(t - t1) > sep) { b2 = dd; t2 = t; }
  }
  float st = P*1.8/95.;
  for (int it = 0; it < 3; it++) {
    float c1 = b1, c2 = b2, n1 = t1, n2 = t2;
    for (int k = 0; k < 7; k++) {
      float o = (float(k)/6. - .5)*st*1.2;
      float ta = t1 + o, tb = t2 + o;
      vec2 da = vec2(u, w) - vec2(ta + kt*R*sin(om*ta), R*cos(om*ta));
      vec2 db = vec2(u, w) - vec2(tb + kt*R*sin(om*tb), R*cos(om*tb));
      float ea = dot(da, da), eb = dot(db, db);
      if (ea < c1) { c1 = ea; n1 = ta; }
      if (eb < c2) { c2 = eb; n2 = tb; }
    }
    b1 = c1; b2 = c2; t1 = n1; t2 = n2; st *= .25;
  }
  float tF = sin(om*t1) >= sin(om*t2) ? t1 : t2;
  float tB = sin(om*t1) >= sin(om*t2) ? t2 : t1;
  float span = 3.5;
  vec3 col = bg;
  vec2 so = vec2(.05, -.12);
  vec2 vs = p - so - O;
  float us = dot(vs, A), wsd = dot(vs, N);
  float shd = 9., tS = us;
  for (int k = 0; k < 32; k++) {
    float t = us + (float(k)/31. - .5)*P*1.8;
    vec2 dv = vec2(us, wsd) - vec2(t + kt*R*sin(om*t), R*cos(om*t));
    float dd = dot(dv, dv);
    if (dd < shd) { shd = dd; tS = t; }
  }
  float stS = P*1.8/31.;
  for (int it = 0; it < 2; it++) {
    float bS = shd, nS = tS;
    for (int k = 0; k < 7; k++) {
      float t = tS + (float(k)/6. - .5)*stS*1.2;
      vec2 dv = vec2(us, wsd) - vec2(t + kt*R*sin(om*t), R*cos(om*t));
      float dd = dot(dv, dv);
      if (dd < bS) { bS = dd; nS = t; }
    }
    shd = bS; tS = nS; stS *= .25;
  }
  float sdd = sqrt(shd);
  col = dim(col, mix(.2, .36, u_dark)*(1. - s01(r*.4, r*3.2, sdd)) + mix(.1, .16, u_dark)*(1. - s01(r*.9, r*1.6, sdd)));
  for (int pass = 0; pass < 2; pass++) {
    float t = pass == 0 ? tB : tF;
    float ct = clamp(t, -span, span);
    vec2 c2 = vec2(ct + kt*R*sin(om*ct), R*cos(om*ct));
    vec2 dl = vec2(u, w) - c2;
    float dist = length(dl);
    float fw = pxu()*1.4 + .007*s01(.25, 1.9, abs(ct - .1));
    float a = 1. - s01(-fw, fw, dist - r);
    if (a > 0.) {
      vec2 tg = normalize(vec2(1. + kt*R*om*cos(om*ct), -R*om*sin(om*ct)));
      float s = dot(dl, vec2(-tg.y, tg.x))/r;
      float zc = sqrt(max(1. - s*s, 0.));
      vec2 nsc = vec2(-tg.y, tg.x)*s;
      vec2 nscr = A*nsc.x + N*nsc.y;
      vec3 n = normalize(vec3(nscr, zc));
      vec3 L = normalize(vec3(normalize(u_light)*.77, .64));
      float dif = sat(dot(n, L));
      vec3 H = normalize(L + vec3(0., 0., 1.));
      float sp = pow(sat(dot(n, H)), 28.);
      float depth = sin(om*ct);
      vec3 c = ramp(sat(.5 + ct/(2.*span)));
      c = vec3(c.x*(.55 + .5*dif), c.yz*(1.05 + .1*(1. - dif)));
      c.x += .17*sp + .04*pow(sat(dot(n, H)), 6.) + .05*pow(1. - zc, 3.);
      c.yz *= 1. - .35*sp;
      float bounce = sat(-dot(nscr, normalize(u_light)))*pow(1. - zc, 1.5);
      c = mix(c, mix(c, u_pal[5], .5), .25*bounce*(1. - u_dark*.5));
      c.x += .03*bounce*(1. - u_dark);
      c.x += .006*gn(p/cssu()*vec2(.5, .5));
      c = dim(c, .25*sat(-depth));
      float endc = s01(span - .02, span + .01, abs(t));
      col = mix(col, c, a*(1. - endc));
    }
  }
  return col;
}

vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], mix(.02, .015, u_dark)), dim(u_pal[5], mix(.1, .3, u_dark)), sat(.5 + .3*p.y + .2*p.x));
  col = mix(col, mix(col, u_pal[1], .35), (1. - u_dark)*sat(.5 - .4*p.y)*.6);
  vec2 cell = floor(p/.04);
  vec2 sp = (cell + .2 + .6*h22(cell))*.04;
  float sz = max(.001, cssu()*.45)*(.6 + 1.1*h21(cell + 3.1));
  col.x += .45*step(.82, h21(cell + 9.7))*exp(-dot(p - sp, p - sp)/(sz*sz))*u_dark;
  vec2 C = vec2(1.0, .28);
  float R = .6;
  float tilt = -.3 - .12*u_opt;
  float fl = mix(.16, .3, u_opt);
  vec2 q = rot(tilt)*(p - C);
  float rho = length(q*vec2(1., 1./fl))/R;
  vec2 Ls = normalize(u_light);
  float rr = rho;
  float band = 0.;
  float rIn = 1.3, rOut = 2.35;
  float ringM = s01(rIn - .01, rIn + .03, rr)*s01(rOut + .02, rOut - .04, rr);
  float cas = 1. - .9*exp(-pow((rr - 1.86)/.025, 2.));
  float fine = .62 + .12*sin(rr*90.) + .14*sin(rr*23. + 1.) + .1*gn(vec2(rr*40., 1.));
  float dens = ringM*cas*sat(fine)*(.55 + .45*s01(rIn, 1.6, rr))*(1. - .4*s01(2.0, rOut, rr));
  vec3 ringC = mix(u_pal[3], u_pal[4], .5 + .5*sin(rr*7.));
  vec2 dp = p - C;
  float pr = length(dp);
  float along = dot(dp, Ls);
  float perp = abs(dot(dp, vec2(-Ls.y, Ls.x)));
  float pShadow = s01(R + .03, R - .03, perp)*s01(.0, -.1, along)*step(.0, q.y);
  vec3 rc = vec3(ringC.x*(1. - .8*pShadow)*(.75 + .25*u_dark) + .05, ringC.yz*(1. - .5*pShadow));
  float front = step(q.y, 0.);
  col = mix(col, rc, sat(dens*(1. - front)*1.05));
  float pa = cover(pr - R);
  if (pa > 0.) {
    vec2 pq = rot(tilt)*dp/R;
    float z = sqrt(max(1. - dot(pq, pq), 0.));
    vec3 n = vec3(dp/R, z);
    float dif = sat(dot(n, normalize(vec3(Ls, .8))));
    float lat = pq.y/max(z*.0 + 1., .01);
    float bands = .5 + .5*sin(lat*14. + 1.5*gn(vec2(pq.x*2., lat*6.)) + 2.*sin(lat*5.));
    vec3 pc = mix(u_pal[0], u_pal[2], bands);
    pc = mix(pc, u_pal[1], .4*exp(-pow(lat/.18, 2.)));
    float term = s01(-.1, .6, dif);
    vec3 night = mix(dim(u_pal[5], .1), vec3(.5, u_pal[5].yz*2.5), 1. - u_dark);
    pc = mix(night, vec3(pc.x*(.55 + .5*term), pc.yz), sm1(term));
    pc.x += .05*pow(1. - z, 3.)*term;
    float rsh = exp(-pow((q.y - fl*R*rIn*.92 - .02)/.012, 2.))*s01(-.3, .2, -q.x);
    pc = dim(pc, .35*rsh*term);
    col = mix(col, pc, pa);
  }
  col = mix(col, rc, sat(dens*front*1.1));
  col.x += .04*dens*front*s01(.0, -.4, q.x)*u_dark;
  return col;
}

vec3 cellIC(vec2 q){
  vec2 ci = floor(q), cf = q - ci;
  float d1 = 9., d2 = 9.;
  vec2 v1 = vec2(0.);
  for (int j = -1; j < 2; j++) for (int i = -1; i < 2; i++) {
    vec2 o = vec2(float(i), float(j));
    vec2 r = o + .15 + .7*h22(ci + o) - cf;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; v1 = r; } else if (d < d2) d2 = d;
  }
  return vec3(v1, sqrt(d2) - sqrt(d1));
}
vec3 wall(vec2 p){
  vec2 M = vec2(.95, .78);
  float dm = length((p - M)*vec2(.8, 1.));
  float day = mix(.6, 1.35, u_opt);
  float z = 1.25 - .32*p.y + .1*p.x;
  vec2 q = vec2(p.x*1.1, p.y*1.5)/z*2.;
  q += .25*vec2(gn(q*.35 + 2.), gn(q*.35 + 7.));
  vec3 c0 = cellIC(q);
  vec2 rv = c0.xy;
  float cup = length(rv);
  vec3 n = normalize(vec3(-rv*.8*s01(.0, .7, c0.z*1.6), 1.));
  vec3 Ld = normalize(vec3(M - p, .6));
  float dif = sat(dot(n, Ld));
  float ridge = exp(-c0.z/.035);
  float thin = exp(-dm*1.1)*day;
  float t = sat(.15 + .45*thin + .35*dif - .15*cup + .1*fbm3(p*1.2 + 3.));
  vec3 col = ramp(t);
  col.x += .05*ridge*(.3 + thin) + .05*pow(dif, 4.);
  float strata = .5 + .5*sin((p.y*7. + .5*sin(p.x*1.3) + .6*fbm3(p*.9))*2.);
  col = mix(col, dim(col, .15), .25*strata*(1. - thin));
  col = mix(col, u_pal[5], .45*s01(.2, 1.7, dm)*(1. - .5*dif));
  col = mix(col, u_pal[4], sat(exp(-dm*dm*7.)*day*.9));
  col.x += .2*exp(-dm/.12)*day;
  return col;
}

float hillM(float x, float i){
  return -.02 - i*.2 + (.1 + .03*i)*sin(x*(.9 + .25*i) + i*2.1) + .06*sin(x*(2.1 + .3*i) - i*1.3) + .012*gn(vec2(x*3., i*7.));
}
vec3 wall(vec2 p){
  vec3 sky = mix(u_pal[1], u_pal[0], sm1((p.y + .1)/1.1));
  vec2 sp = vec2(-.75, .3);
  float sr = length(p - sp);
  sky = mix(sky, u_pal[5], .6*exp(-sr*1.7));
  vec3 col = sky;
  float haze = mix(.35, .9, u_opt);
  for (int k = 0; k < 5; k++) {
    float i = float(k);
    float e = .01;
    float y = hillM(p.x, i);
    float sl = (hillM(p.x + e, i) - y)/e;
    float a = cover((p.y - y)/sqrt(1. + sl*sl));
    float u = i/4.;
    vec3 m = mix(u_pal[2], u_pal[3], sm1(u*2.));
    m = mix(m, u_pal[4], sm1(u*2. - 1.));
    m = mix(m, u_pal[1], (1. - u)*(1. - u)*haze*.8);
    m = mix(m, u_pal[5], .22*(1. - u)*exp(-length(p - sp)*1.3));
    m.x += .045*clamp(sl*.9, -1., 1.)*(.35 + .65*u);
    float dep = max(y - p.y, 0.);
    m = dim(m, .12*s01(.0, .35, dep)*(.5 + u));
    m.x += .05*exp(-dep/.018)*(1. - u*.4);
    m.x += .01*u*gn(p*vec2(28., 80.));
    col = mix(col, m, a);
  }
  return col;
}

float duneH(vec2 q){
  vec2 w = q + .8*vec2(gn(q*.18 + 3.), gn(q*.18 + 8.));
  float r1 = 1. - abs(gn(w*vec2(.42, .3)));
  float r2 = 1. - abs(gn(w*vec2(.9, .7) + 5.));
  return r1*r1*.9 + r2*r2*.25;
}
vec3 wall(vec2 p){
  float hz = .3;
  vec3 sky = mix(u_pal[4], u_pal[5], sm1((p.y - hz)/(1. - hz)*1.3));
  vec2 sp = vec2(-1.05, hz + .12);
  sky = mix(sky, lift(u_pal[3], .04), .5*exp(-length((p - sp)*vec2(.6, 1.))*3.));
  if (p.y > hz + .003) return sky;
  float z = .6/(hz - p.y + .01);
  vec2 q = vec2(p.x*z, z*1.6);
  float e = .015 + .004*z;
  float h = duneH(q), hx = duneH(q + vec2(e, 0.)), hz2 = duneH(q + vec2(0., e));
  vec3 n = normalize(vec3(-(hx - h)/e*.9, 1., -(hz2 - h)/e*.9));
  float el = mix(.15, .6, u_opt);
  vec3 L = normalize(vec3(-.9, el, .35));
  float dif = dot(n, L);
  float t = sat(dif*1.15 + .1);
  vec3 c = mix(u_pal[0], u_pal[1], sm1(t*3.));
  c = mix(c, u_pal[2], sm1(t*3. - 1.));
  c = mix(c, u_pal[3], sm1(t*3. - 2.));
  c.x += .012*gn(vec2(q.x*14., q.y*5.))*exp(-z*.3);
  float fog = 1. - exp(-z*.06);
  c = mix(c, u_pal[4], fog);
  return mix(c, sky, s01(hz - .004, hz + .003, p.y));
}

vec3 fieldF(vec2 p, float b){
  vec3 c = mix(u_pal[5], dim(u_pal[5], .12), sat(.5 - p.y*.3));
  float k = 1./(1. + b*2.2);
  vec2 d0 = p - vec2(-.95, .42), d1 = p - vec2(.75, .62), d2 = p - vec2(.18, -.58), d3 = p - vec2(1.3, -.45);
  c = mix(c, u_pal[0], .92*exp(-dot(d0, d0)*1.7*k));
  c = mix(c, u_pal[1], .88*exp(-dot(d1, d1)*2.1*k));
  c = mix(c, u_pal[2], .88*exp(-dot(d2, d2)*1.9*k));
  c = mix(c, u_pal[3], .75*exp(-dot(d3, d3)*2.8*k));
  return c;
}
void pane(inout vec3 col, vec2 p, vec2 c, vec2 hs, float r, float ang, float lvl){
  vec2 q = rot(-ang)*(p - c);
  float d = sdBox(q, hs, r);
  vec2 qs = rot(-ang)*(p - c - vec2(.035, -.07));
  float sh = 1. - s01(-.1, .18, sdBox(qs, hs, r));
  float a = cover(d);
  col = dim(col, mix(.2, .32, u_dark)*sh*(1. - a));
  float e = .003;
  vec2 gr = vec2(sdBox(q + vec2(e, 0.), hs, r) - d, sdBox(q + vec2(0., e), hs, r) - d)/e;
  vec2 n = rot(ang)*gr;
  float rim = exp(min(d, 0.)/.06);
  float fr = mix(.3, 1., u_opt);
  vec3 g = mix(fieldF(p - n*.07*rim, fr*(.7 + lvl*.4)), col, .25);
  g = lift(g, mix(.035, .07, u_opt) + .02*lvl);
  g.x += .025*(q.y/hs.y);
  float lit = dot(n, normalize(vec2(-.6, .8)));
  float band = exp(min(d, 0.)/.005);
  g.x += band*(.1 + .22*max(lit, 0.)) + .045*exp(min(d, 0.)/.035)*max(lit, 0.);
  g.x -= band*.05*max(-lit, 0.);
  g.x += .01*fr*gn(p/cssu()*.4);
  col = mix(col, g, a);
}
vec3 wall(vec2 p){
  vec3 col = fieldF(p, 0.);
  pane(col, p, vec2(-.68, -.3), vec2(.4, .4), .4, 0., 0.);
  pane(col, p, vec2(.42, .06), vec2(.62, .48), .17, .12, 1.);
  pane(col, p, vec2(1.12, .66), vec2(.3, .11), .11, -.18, .5);
  return col;
}

float ribY(float x, float i){
  return -.8 + i*.47 + (.2 + .05*i)*sin(x*(.72 + .1*i) + i*1.9 + .3) + .08*sin(x*1.55 - i*2.4);
}
vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], .03), dim(u_pal[5], .3), sat(.55 - .3*p.y + .12*p.x));
  col = mix(col, u_pal[2], .25*exp(-dot(p - vec2(-.6, .5), p - vec2(-.6, .5))*.5));
  float gl = mix(.25, 1., u_opt);
  vec3 K = normalize(vec3(-.35, .72, .6));
  vec3 H = normalize(K + vec3(0., 0., 1.));
  for (int k = 0; k < 4; k++) {
    float i = float(k);
    float e = .01;
    float y = ribY(p.x, i);
    float sl = (ribY(p.x + e, i) - y)/e;
    float nr = sqrt(1. + sl*sl);
    float w = .21 + .04*sin(p.x*.8 + i*3.1);
    float d = (p.y - y)/nr;
    float ds = (p.y + .06 - ribY(p.x - .04, i))/nr;
    float sh = 1. - s01(w*.55, w + .2, abs(ds));
    float a = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, abs(d) - w);
    col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
    float v = clamp(d/w, -1., 1.);
    vec2 ac = vec2(-sl, 1.)/nr;
    vec3 n = normalize(vec3(ac*v, sqrt(max(1. - v*v, 0.)) + .02));
    float kw = sat(dot(n, K)*.62 + .38);
    kw = kw*kw*(3. - 2.*kw);
    vec3 c = mix(u_pal[k], u_pal[k + 1], .5 + .5*sin(p.x*.55 + i*1.7));
    c = vec3(c.x*(.5 + .56*kw), c.yz*(1. + .5*kw*(1. - kw) - .1*kw*kw));
    c.x += .05*sat(-v)*(1. - kw)*s01(.4, 1., abs(v));
    float nh = sat(dot(n, H));
    c.x += gl*(.16*pow(nh, 40.) + .05*pow(nh, 6.));
    c.yz *= 1. - .4*gl*pow(nh, 40.);
    col = mix(col, c, a);
  }
  return col;
}

void sheet(inout vec3 col, vec2 p, vec2 C, float Rad, float R, vec3 face){
  float u = length(p - C) - Rad;
  vec2 dir = (p - C)/max(length(p - C), 1e-4);
  float lit = dot(-dir, normalize(vec2(-.5, .8)));
  float sh = exp(-max(u, 0.)/(.45*R + .05))*s01(-.03, .005, u)*(.65 - .35*lit);
  float a = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, u);
  col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
  vec3 c = face;
  c.x += .035*s01(.0, -1.6, u) - .02 - .03*dot(p, normalize(vec2(.6, -.8)))*.4;
  c.x += .004*gn(p/cssu()*.3);
  float ui = u + 2.*R;
  c = dim(c, .22*exp(-max(-ui, 0.)/.07)*s01(.0, -.004, ui));
  float s = clamp((u + R)/R, -1., 1.);
  float inR = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, abs(u + R) - R);
  vec3 n = normalize(vec3(-dir*s, sqrt(max(1. - s*s, 0.)) + .02));
  float kw = sat(dot(n, normalize(vec3(-.45, .65, .6)))*.6 + .4);
  kw = kw*kw*(3. - 2.*kw);
  vec3 b = mix(face, u_pal[4], .55);
  b = vec3(b.x*(.62 + .45*kw), b.yz*(1. + .3*(1. - kw)));
  b.x += .07*pow(sat(dot(n, normalize(vec3(-.3, .5, .81)))), 18.);
  c = mix(c, b, inR);
  col = mix(col, c, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[0], dim(u_pal[0], .25), sat(.5 - .3*p.y + .2*p.x));
  col.x += .003*gn(p/cssu()*.3);
  float R = mix(.04, .13, u_opt);
  sheet(col, p, vec2(-2.7, -2.5), 3.25, R*1.1, u_pal[1]);
  sheet(col, p, vec2(3.0, 2.6), 3.05, R, u_pal[2]);
  sheet(col, p, vec2(2.9, -2.3), 2.25, R*.85, u_pal[3]);
  return col;
}

float drop(vec2 p, vec2 c, float R, float k){
  float r = length(p - c);
  float x = r - R;
  return (sin(x*k)*exp(-x*x*16.) + .45*sin((r - R*.6)*k*1.15)*exp(-pow(r - R*.6, 2.)*30.))*exp(-r*.8);
}
float hR(vec2 p){
  return drop(p, vec2(.6, .18), .62, 34.) + .8*drop(p, vec2(-.85, -.38), .45, 40.) + .6*drop(p, vec2(.05, -.82), .3, 46.) + .05*gn(p*1.5);
}
vec3 wall(vec2 p){
  float e = .002;
  float A = mix(.0015, .006, u_opt);
  float h = hR(p);
  vec2 g = vec2(hR(p + vec2(e, 0.)) - h, hR(p + vec2(0., e)) - h)/e*A;
  float t = .5 + .14*(p.x + g.x*14.) - .16*(p.y + g.y*14.);
  vec3 c = ramp(t);
  vec3 n = normalize(vec3(-g*3., 1.));
  float sp = pow(sat(dot(n, normalize(vec3(-.4, .5, .77)))), 60.);
  c = mix(c, u_pal[5], sat(sp*.6));
  c.x += .05*(n.y - n.x)*2.;
  return c;
}

float hC(vec2 p){ return fbm3(p*.42 + vec2(2., 7.))*1.1 + .08*gn(p*1.7) + .22*sin(p.x*.6 + 1.); }
vec3 wall(vec2 p){
  float e = .003;
  float h = hC(p);
  vec2 g = vec2(hC(p + vec2(e, 0.)) - h, hC(p + vec2(0., e)) - h)/e;
  vec3 c = ramp(sat(h*.62 + .5));
  vec3 n = normalize(vec3(-g*.5, 1.));
  c.x += .07*(dot(n, normalize(vec3(-.6, .7, .55))) - .72);
  float st = .07;
  float v = h/st;
  float dl = abs(fract(v + .5) - .5)*st/max(length(g), .02);
  float major = step(4.5, mod(floor(v + .5) + 50., 5.));
  float lw = cssu()*(.55 + .6*major);
  float line = 1. - s01(lw, lw + pxu()*1.3, dl);
  c = mix(c, u_pal[5], line*mix(.2, .6, u_opt)*(.7 + .3*major));
  return c;
}

float washW(vec2 p, vec2 c, float r, float seed, float bleed){
  vec2 q = p + (.2 + .15*bleed)*vec2(fbm3(p*1.1 + seed), fbm3(p*1.1 + seed + 5.));
  vec2 v = rot(seed)*(q - c);
  return (r - length(v*vec2(.72, 1.25)))/r + .32*fbm(p*1.8 + seed*1.7);
}
void glaze(inout vec3 col, vec2 p, vec3 pig, vec3 paper, float f, float tooth, float seed){
  float inside = s01(-.01, .05, f);
  float edge = exp(-max(f, 0.)/.035)*inside;
  float dens = inside*(mix(.42, .62, u_dark) + .2*fbm3(vec2(f*3., seed))) + .45*edge;
  float gran = s01(.0, .8, gn(p/cssu()*.42 + seed*7.) + .6*gn(p/cssu()*.13 + seed));
  float floc = fbm3(p*7. + seed*3.);
  dens *= .72 + .32*tooth + .4*gran*mix(.6, 1., u_dark) + .18*floc;
  dens = sat(dens);
  col = vec3(col.x*mix(1., pig.x/paper.x, dens), col.yz + (pig.yz - paper.yz)*dens);
}
vec3 wall(vec2 p){
  vec3 paper = u_pal[5];
  float tooth = fbm3(p/cssu()*.07);
  vec3 col = paper;
  col.x += .012*tooth;
  float b = u_opt;
  glaze(col, p, u_pal[0], paper, washW(p, vec2(-.85, .35), .78, 1.3, b), tooth, 1.);
  glaze(col, p, u_pal[1], paper, washW(p, vec2(.55, .5), .62, 4.1, b), tooth, 2.);
  glaze(col, p, u_pal[2], paper, washW(p, vec2(.95, -.45), .7, 7.7, b), tooth, 3.);
  glaze(col, p, u_pal[3], paper, washW(p, vec2(-.2, -.55), .55, 9.2, b), tooth, 4.);
  glaze(col, p, u_pal[4], paper, washW(p, vec2(-1.45, -.7), .45, 12.5, b), tooth, 5.);
  return col;
}

float archD(vec2 p, vec2 c){ vec2 q = p - c; return q.y > 0. ? length(q) : abs(q.x); }
vec3 bandC(float k){
  vec3 c = u_pal[0];
  c = mix(c, u_pal[1], step(.5, k));
  c = mix(c, u_pal[2], step(1.5, k));
  c = mix(c, u_pal[3], step(2.5, k));
  return c;
}
void arches(inout vec3 col, vec2 p, vec2 c, float r0, float w, float rev){
  float d = archD(p, c);
  float outer = r0 + 4.*w;
  float sk = mix(.12, .4, u_opt);
  float dsh = archD(p - vec2(.03, -.045), c);
  float sh = (1. - s01(outer - .03, outer + .14, dsh))*s01(r0 - .12, r0 + .03, dsh);
  float a = cover(d - outer)*(1. - cover(d - r0));
  col = dim(col, sk*sh*(1. - a));
  float x = (d - r0)/w;
  float k = clamp(floor(x), 0., 3.);
  float f = fract(x);
  float kk = rev > .5 ? 3. - k : k;
  float kp = rev > .5 ? 4. - k : k - 1.;
  vec3 bc = bandC(kk);
  vec3 prev = bandC(clamp(kp, 0., 3.));
  bc = mix(prev, bc, k > .5 ? s01(0., pxu()*1.5/w, f) : 1.);
  bc = dim(bc, sk*.5*exp(-f/.07)*step(.5, k));
  bc.x += .02*(f - .5);
  col = mix(col, bc, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], dim(u_pal[5], .1), sat(.5 - p.y*.35));
  float sd = length(p - vec2(-.42, .5));
  col = mix(col, u_pal[4], cover(sd - .2));
  arches(col, p, vec2(.62, -.42), .2, .2, 0.);
  arches(col, p, vec2(-1.08, -.78), .1, .12, 1.);
  return col;
}

float sS(vec2 p){
  vec2 q = p*.9;
  q += .38*vec2(fbm3(q*.8), fbm3(q*.8 + 4.));
  return q.y*2.1 + .55*sin(q.x*1.25 + q.y*.8) + .28*fbm(q*1.2);
}
vec3 wall(vec2 p){
  float e = .003;
  float s = sS(p);
  vec2 g = vec2(sS(p + vec2(e, 0.)) - s, sS(p + vec2(0., e)) - s)/e;
  float bd = mix(.4, 1., u_opt);
  float rel = sin(s*7.)*.5 + sin(s*17. + 1.)*.2;
  vec3 c = ramp(.5 + .48*sin(s*1.15 + .3));
  c.x += bd*(.035*sin(s*7.) + .018*sin(s*17. + 1.) + .01*sin(s*41.));
  float gl = length(g);
  vec2 gd = g/max(gl, 1e-3);
  float sh = dot(gd, normalize(vec2(-.6, .8)))*cos(s*7.);
  c.x += .03*bd*sh;
  float groove = exp(-abs(fract(s*.6) - .5)*40.)*bd;
  c = mix(c, u_pal[5], .2*groove);
  c = dim(c, .1*s01(.5, 2.2, length(p*vec2(.7, 1.))));
  return c;
}

float holeT(vec2 p, float k){
  float t = k/5.;
  // the near sheets move most with the viewer (Perspective); the back sheet stays
  p += u_tilt*(1. - t);
  vec2 c = mix(vec2(-.2, .05), vec2(.62, -.08), sm1(t)) + vec2(0., .05*sin(t*3.));
  float r = mix(1.32, .26, pow(t, .85));
  vec2 q = rot(.25 + .5*t)*(p - c);
  q *= vec2(.78 + .1*t, 1.);
  float a = atan(q.y, q.x);
  return length(q) - r*(1. + .055*sin(2.*a + k*1.3) + .03*sin(3.*a - k*2.1));
}
vec3 wall(vec2 p){
  vec2 L = normalize(vec2(-.55, .83));
  float gap = mix(.025, .075, u_opt);
  vec3 col = u_pal[5];
  float done = 0.;
  float prevD = -1.;
  for (int j = 0; j < 6; j++) {
    float k = float(j);
    float d = j < 5 ? holeT(p, k) : 1.;
    if (done < .5 && d > 0.) {
      done = 1.;
      float t = k/5.;
      vec3 c = j < 5 ? ramp(t*.95) : u_pal[5];
      float inner = j < 5 ? s01(.7, -.2, d) : 1.;
      if (j == 5) { vec2 cc = p - vec2(.62, -.08); c = mix(u_pal[4], u_pal[5], exp(-dot(cc, cc)*9.)); }
      // light falls in from the far end: each sheet is brighter towards its opening
      c.x += .06*exp(-d/.25)*(.4 + .6*t);
      c.x -= .05*(1. - t)*s01(.0, 1.2, d);
      c.x += .004*gn(p/cssu()*.35 + k*13.) + .006*gn(p/cssu()*.07 + k*7.);
      if (j > 0) {
        float ds = holeT(p + L*gap*(1.2 - .2*k/5.), k - 1.);
        float sh = s01(-.05, .03, ds);
        float ao = exp(max(prevD, -1.)/.07*1.);
        c = dim(c, mix(.34, .45, u_dark)*sh + .16*ao);
      }
      if (j < 5) {
        float e = exp(-d/(cssu()*1.6));
        vec2 gr = vec2(holeT(p + vec2(.002, 0.), k) - d, holeT(p + vec2(0., .002), k) - d)/.002;
        float lit = dot(normalize(gr + 1e-5), -L);
        c.x += e*(.05 + .13*max(lit, 0.)) - e*.05*max(-lit, 0.);
      }
      col = c;
    }
    if (done < .5) prevD = d;
  }
  return col;
}

vec2 vor(vec2 x){
  vec2 n = floor(x), f = x - n;
  float d1 = 8., d2 = 8.;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 g = vec2(float(i), float(j));
    vec2 o = h22(n + g);
    vec2 r = g + o - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
  }
  return vec2(sqrt(d1), sqrt(d2));
}
float bowlH(float r){
  float R = 1.18;
  float lip = exp(-pow((r - R)/.045, 2.))*.05;
  float well = r < R ? -.32*(1. - pow(r/R, 2.2)) : -.6*s01(R, R + .09, r);
  return well + lip;
}
vec3 wall(vec2 p){
  vec2 C = vec2(.92, -.28);
  vec2 d = p - C;
  float r = length(d);
  vec3 L = normalize(vec3(-.55, .65, .55));
  // linen cloth
  vec3 cloth = u_pal[0];
  vec2 w = p/cssu();
  float th = .5 + .5*sin(w.x*1.1 + .6*gn(w*.05))*.5 + .5*sin(w.y*1.1 + .6*gn(w*.05 + 3.))*.5;
  cloth.x += .012*(th - .5) + .008*gn(w*.02) + .03*sat(.5 - p.y*.3 - p.x*.2);
  // the bowl's shadow on the cloth
  float rs = length(p - C + vec2(.12, .16));
  cloth = dim(cloth, .32*(1. - s01(1.05, 1.5, rs)));
  cloth = dim(cloth, .15*(1. - s01(1.2, 1.3, r)));
  vec3 col = cloth;
  float R = 1.18 + .055;
  float a = cover(r - R);
  if (a > 0.) {
    float e = .002;
    float h0 = bowlH(r), h1 = bowlH(r + e);
    float dh = (h1 - h0)/e;
    vec2 dir = d/max(r, 1e-4);
    vec3 n = normalize(vec3(-dir*dh, 1.));
    // glaze thickness: pooled in the well, thin over the lip
    float thick = sat(.25 + .9*(1. - r/1.18)) * (1. - exp(-pow((r - 1.18)/.05, 2.))*.85);
    vec3 g = mix(u_pal[4], mix(u_pal[2], u_pal[1], sm1(1. - r/1.1)), sat(thick*1.2));
    float dif = sat(dot(n, L)*.8 + .3);
    g.x *= .72 + .36*dif;
    // the bowl shades its own far wall
    float self = s01(-.2, .9, dot(dir, -L.xy))*s01(.0, 1.1, r)*(r < 1.18 ? 1. : 0.);
    g = dim(g, .22*self);
    vec3 Rv = reflect(vec3(0., 0., -1.), n);
    float win = s01(.6, .95, dot(Rv, normalize(vec3(-.5, .6, .62))));
    g.x += .16*win*win + .05*pow(sat(dot(Rv, L)), 30.);
    vec2 v = vor(p/cssu()*.045 + 5.);
    float cr = 1. - s01(.0, .035 + .04*(1. - thick), v.y - v.x);
    g = mix(g, dim(g, .35), cr*mix(.0, .55, u_opt)*thick);
    g.x += .006*gn(p*60.);
    col = mix(col, g, a);
  }
  return col;
}

vec3 lightC(float fi){
  float m = mod(fi, 4.);
  return m < .5 ? u_pal[1] : m < 1.5 ? u_pal[2] : m < 2.5 ? u_pal[3] : u_pal[4];
}
// the far shore: a row of narrow houses of different heights, each painted its own colour
float roofH(float x){ return .03 + .035*step(.55, h21(vec2(floor(x*3.3 + 7.), 3.))) + .015*step(.5, h21(vec2(floor(x*11.), 5.))) + .012*h21(vec2(floor(x*3.3 + 7.), 6.)); }
vec3 houseC(float x, float y){
  float id = floor(x*3.3 + 7.);
  vec3 c = lightC(id + floor(h21(vec2(id, 8.))*3.));
  // windows: a faint row of darker panes, and the sunlit face a touch brighter on its left
  float wx = fract(x*26.), wy = fract(y*95.);
  c.x -= .035*s01(.3, .4, wx)*s01(.75, .65, wx)*s01(.3, .4, wy)*s01(.8, .7, wy);
  c.x += .02*s01(.25, .0, fract(x*3.3 + 7.));
  return c;
}
vec3 wall(vec2 p){
  float hz = .58;
  float sw = mix(.35, 1.2, u_opt);
  float day = 1. - u_dark;
  vec2 sun = vec2(-.95, hz + .07);
  vec3 sky = mix(u_pal[5], u_pal[0], sm1((p.y - hz)/.55));
  sky = mix(sky, lift(u_pal[5], .05), day*.7*exp(-length((p - sun)*vec2(.55, 1.))*3.));
  vec3 col = sky;
  float qt = hz + roofH(p.x);
  vec3 quay = dim(u_pal[0], .25);
  float wid = mix(.05, .02, u_dark);
  if (p.y >= hz) {
    vec3 fac = mix(quay, houseC(p.x, p.y), day);
    fac = mix(fac, dim(mix(u_pal[0], u_pal[5], .4), .15), day*s01(hz + .007, hz + .003, p.y));
    col = mix(col, fac, cover(p.y - qt));
    for (int i = 0; i < 11; i++) {
      float fi = float(i);
      float xi = -1.95 + fi*.37 + .3*(h21(vec2(fi, 2.)) - .5) + .12*sin(fi*2.3);
      vec2 d = p - vec2(xi, hz + .022);
      float k = (.5 + .5*h21(vec2(fi, 9.)))*u_dark;
      col = mix(col, lightC(fi), sat(k*(exp(-dot(d, d)/.00006) + .25*exp(-length(d)/.03))));
    }
  } else {
    float dz = hz - p.y;
    float Z = 1./(dz + .025);
    vec2 wq = vec2(p.x*Z*.35, Z*2.4);
    float wv = gn(wq) + .5*gn(wq*vec2(2.1, 2.3) + 3.) + .25*gn(wq*vec2(4.3, 4.1) + 7.);
    float dx = sw*.045*wv*(.25 + dz*1.2);
    vec3 water = mix(u_pal[5], dim(u_pal[0], .05), sm1(dz/.9));
    water.x += .025*wv*s01(.0, .3, dz);
    float sharp = s01(.0, .6, dz);
    float facet = s01(mix(-.35, -.05, sharp), mix(.6, .35, sharp), wv);
    col = water;
    // by day the houses lie in the water, stretched and broken by the swell
    float xr = p.x + dx*.8;
    float rl = roofH(xr)*4.;
    float rm = s01(rl, rl*.55, dz + .25*rl*wv)*mix(.5, 1., facet)*mix(1., .35 + .65*facet, s01(.0, .2, dz));
    vec3 rc = mix(houseC(xr, hz + dz*.25), water, .2 + .4*s01(.0, rl, dz));
    col = mix(col, rc, day*.92*rm);
    // the glow of the sky under the sun, laid along the water
    col = mix(col, lift(u_pal[5], .03), day*.35*exp(-abs(p.x - sun.x)/(.25 + .5*dz))*exp(-dz*1.5));
    // the low sun's path, glittering on the facets towards it
    float path = exp(-abs(p.x + dx*.6 - sun.x)/(.03 + .22*dz))*pow(facet, 3.)*exp(-dz*.9);
    col = mix(col, lift(u_pal[5], .07), day*sat(path*1.8));
    // by night the lights of the quay make long trails
    vec3 acc = vec3(0.);
    float tot = 0.;
    for (int i = 0; i < 11; i++) {
      float fi = float(i);
      float xi = -1.95 + fi*.37 + .3*(h21(vec2(fi, 2.)) - .5) + .12*sin(fi*2.3);
      float w = (wid + .035*dz*sw)*(.6 + .8*h21(vec2(fi, 4.)));
      float k = exp(-pow((p.x + dx - xi)/w, 2.))*(.5 + .5*h21(vec2(fi, 9.)));
      acc += lightC(fi)*k; tot += k;
    }
    float tk = sat(tot)*mix(.85, 1., facet*facet)*mix(1., .2 + .8*facet, s01(.0, .25, dz));
    vec3 tc = acc/max(tot, 1e-4);
    tc = mix(tc, lift(tc, .05), facet*.5);
    col = mix(col, tc, tk*.9*u_dark*exp(-dz*.3));
  }
  return col;
}

float cofM(vec2 c){ return min(min(c.x, 1. - c.x)*1.25, min(c.y, 1. - c.y)); }
vec3 wall(vec2 p){
  vec3 rd = normalize(vec3(p.x, p.y, 1.15));
  rd.yz = rot(-.85)*rd.yz;
  rd.xz = rot(-.68)*rd.xz;
  float ca = .965;
  float y = rd.y;
  vec3 sd = normalize(vec3(-.8, mix(.48, .62, u_opt), -.3));
  vec3 col;
  if (y > ca) {
    col = mix(u_pal[4], u_pal[5], s01(.6, 1., dot(rd, normalize(sd + vec3(0., 1.5, 0.)))));
    col = mix(col, lift(u_pal[3], .03), s01(ca + .003, ca, y));
  } else {
    float el = asin(clamp(y, -1., 1.));
    float az = atan(rd.x, rd.z);
    float rows = 5.;
    float e0 = .12, e1 = 1.2;
    float v = (el - e0)/(e1 - e0)*rows;
    float u = az/(2.*PI)*28.;
    vec2 cf = vec2(u - floor(u), v - floor(v));
    float inC = step(0., v)*step(v, rows);
    float aa = pxu()*rows/(e1 - e0)*1.2/max(cos(el)*.0 + 1., 1.);
    float m = cofM(cf);
    // three steps down into each coffer: rib, first bevel, ledge, second bevel, panel
    float s1 = s01(.09, .09 + aa, m), s2 = s01(.17, .17 + aa, m), s3 = s01(.23, .23 + aa, m), s4 = s01(.3, .3 + aa, m);
    float bevel = (s1 - s2) + (s3 - s4);
    float horiz = step(min(cf.x, 1. - cf.x)*1.25, min(cf.y, 1. - cf.y));
    float up = cf.y < .5 ? 1. : -1.;
    float side = cf.x < .5 ? 1. : -1.;
    float face = mix(up*.8, side*.35, horiz);
    float depth = (s1*.35 + s2*.25 + s3*.2 + s4*.2)*inC;
    float amb = .28 + .72*pow(sat(y), 1.4);
    vec3 c = mix(u_pal[0], u_pal[2], amb);
    c = mix(c, u_pal[1], .3*(1. - amb));
    c.x -= .05*depth*(1. - .3*amb);
    c.x += .035*face*bevel*inC*(.4 + amb);
    c.x += .007*gn(rd.xz*60. + rd.y*9.) + .004*gn(p/cssu()*.3);
    // the sun through the eye: follow the ray back towards the sun
    float tt = (ca - y)/sd.y;
    vec3 Q = rd + sd*tt;
    float rq = length(Q.xz)/sqrt(1. - ca*ca);
    float spot = s01(1.03, .95, rq);
    // the ribs cast short shadows into the coffers on the side away from the light
    vec2 sh = cf + vec2(.1, .14);
    float shadow = inC*s4*(1. - s01(.07, .12, cofM(sh - floor(sh))))*0. + inC*(1. - s01(.06, .1, cofM(fract(cf + vec2(.09, .13)))))*s1;
    vec3 sun = u_pal[3];
    sun.x += .06*face*bevel*inC - .02*depth;
    sun = dim(sun, .42*shadow);
    c = mix(c, sun, .85*spot);
    c = mix(c, mix(u_pal[2], u_pal[3], .5), .18*exp(-max(rq - 1., 0.)*1.3)*(1. - spot));
    col = mix(c, dim(c, .3), s01(ca - .01, ca, y));
  }
  return col;
}

vec3 skyS(vec2 p, float hz){
  float y = p.y - hz;
  vec3 c = mix(u_pal[2], u_pal[1], s01(.0, .3, y));
  c = mix(c, u_pal[0], s01(.2, 1.1, y));
  c = mix(c, u_pal[3], .5*exp(-y/.05));
  // soft clouds that flatten towards the horizon
  vec2 cq = vec2(p.x*.9, y*3.2/(y + .25));
  float cl = s01(.05, .6, fbm(cq*vec2(1.2, 2.4) + vec2(3., 1.)));
  vec3 cc = mix(u_pal[3], u_pal[4], s01(.0, .8, y));
  cc.x += .05*fbm3(cq*4.);
  return mix(c, cc, cl*.55*s01(.0, .06, y));
}
float hexE(vec2 x){
  vec2 n = floor(x), f = x - n;
  float d1 = 8., d2 = 8.;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 g = vec2(float(i), float(j));
    vec2 r = g + .5 + .75*(h22(n + g) - .5) - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
  }
  return sqrt(d2) - sqrt(d1);
}
vec3 wall(vec2 p){
  float hz = -.08;
  if (p.y >= hz) return skyS(p, hz);
  float dz = hz - p.y;
  vec3 r = skyS(vec2(p.x, hz + dz), hz);
  r = dim(r, .06 + .08*s01(.0, .8, dz));
  float wt = mix(.25, .9, u_opt);
  // the crust in perspective: ridges thin out towards the horizon and stand clear of the water near you
  float Z = .7/(dz + .002);
  vec2 X = vec2(p.x*Z, Z*1.6)*1.3;
  float e = hexE(X);
  float rw = .03 + .03*gn(X*.7);
  float ridge = (1. - s01(rw*.4, rw, e))*s01(.05, .5, dz)*(.5 + .5*gn(X*.4 + 3.));
  float dry = s01(wt, wt - .35, .5 + .5*gn(X*.25) - dz*.3);
  vec3 salt = mix(u_pal[5], u_pal[4], .3);
  salt.x += .03*gn(X*3.);
  vec3 col = mix(r, salt, sat(ridge)*mix(.12, .5, dry));
  col = dim(col, .06*exp(-e/(rw*3.))*s01(.05, .5, dz)*(1. - dry));
  col = mix(col, r, s01(.03, .0, dz)*.0);
  return col;
}

vec3 cardD(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], s01(-1.3, 1.1, p.y*.6 - p.x*.35));
  c.x += .008*gn(p/cssu()*.25) + .004*gn(p/cssu()*.9);
  return c;
}
void drop(inout vec3 col, vec2 p, vec2 c, float R, float lt){
  vec2 Ld = normalize(vec2(-.6, .75));
  vec2 q = (p - c)/R;
  float r = length(q);
  // the shadow falls away from the light, with the light the drop focused gathered inside it
  vec2 qs = (p - c + Ld*R*.55)/R;
  float rs = length(qs*vec2(1., 1.));
  float sh = s01(1.05, .75, rs);
  vec2 qf = (p - c + Ld*R*.62)/R;
  float foc = exp(-dot(qf, qf)/.1);
  col = dim(col, .32*sh*(1. - s01(.95, 1.02, r)*0.));
  col = mix(col, lift(u_pal[4], .06), .7*foc*lt*s01(.9, 1., r));
  float a = s01(1. + pxu()*1.2/R, 1. - pxu()*1.2/R, r);
  if (a <= 0.) return;
  // the drop is a lens: the card under it seen through it, magnified and turned over
  float z = sqrt(max(1. - r*r, 0.));
  vec3 n = normalize(vec3(q, z*.8 + .05));
  vec3 inside = cardD(c - q*R*.55);
  inside = mix(inside, u_pal[4], .3*s01(.0, .8, dot(-q, Ld)));
  inside.x += .05*s01(.3, 1., dot(-q, Ld));
  // a dark ring at the rim where the drop turns the light away
  float rim = s01(.55, .97, r);
  inside = mix(inside, u_pal[2], .75*rim*rim);
  inside = dim(inside, .25*rim*s01(-.2, .8, dot(q, Ld)));
  // the window, reflected small and sharp, and a softer second reflection
  vec2 wq = q - Ld*.42;
  float win = s01(.11, .085, sdBox(rot(.3)*wq, vec2(.1, .07), .03));
  inside = mix(inside, u_pal[3], win*.95*lt);
  float soft = exp(-dot(q + Ld*.55, q + Ld*.55)/.02)*.35;
  inside = mix(inside, u_pal[3], soft*lt);
  col = mix(col, inside, a);
}
vec3 wall(vec2 p){
  vec3 col = cardD(p);
  float lt = mix(.55, 1., u_opt);
  drop(col, p, vec2(.95, -.32), .36, lt);
  drop(col, p, vec2(1.42, .3), .15, lt);
  drop(col, p, vec2(.38, -.75), .1, lt);
  drop(col, p, vec2(-1.2, .55), .07, lt);
  drop(col, p, vec2(1.25, -.85), .06, lt);
  return col;
}

vec3 skyW(vec3 d, vec3 sd){
  vec3 c = mix(u_pal[3], u_pal[2], s01(.0, .12, d.y));
  c = mix(c, u_pal[1], s01(.08, .5, d.y));
  c = mix(c, u_pal[0], s01(.4, 1., d.y));
  float s = sat(dot(d, sd));
  c = mix(c, u_pal[5], .7*pow(s, 40.) + .25*pow(s, 5.)*s01(.3, .0, d.y));
  return c;
}
float swH(vec2 x, float a){
  float h = a*(.6*sin(x.y*.42 + .3*x.x + .8*gn(x*.1)) + .25*sin(x.y*.9 - .45*x.x + 1.));
  return h + .05*gn(x*.7) + .015*gn(x*2.1 + 4.) + .005*gn(x*5.3);
}
vec3 wall(vec2 p){
  vec3 ro = vec3(0., 1.2, 0.);
  vec3 rd = normalize(vec3(p.x, p.y - .22, 2.));
  vec3 sd = normalize(vec3(.55, .06, 1.));
  float a = mix(.2, .65, u_opt);
  if (rd.y >= 0.) return skyW(rd, sd);
  float t = -ro.y/rd.y;
  // two refinement steps onto the swell
  for (int i = 0; i < 3; i++) { vec3 x = ro + rd*t; t = (swH(x.xz, a) - ro.y)/rd.y; }
  vec3 x = ro + rd*t;
  float e = .02 + .004*t;
  float h = swH(x.xz, a);
  vec3 n = normalize(vec3(-(swH(x.xz + vec2(e, 0.), a) - h)/e, 1., -(swH(x.xz + vec2(0., e), a) - h)/e));
  vec3 r = reflect(rd, n);
  r.y = abs(r.y);
  float fr = .04 + .96*pow(1. - sat(dot(-rd, n)), 5.);
  vec3 deep = mix(u_pal[4], u_pal[0], s01(.0, .6, -rd.y*3.));
  deep = mix(deep, u_pal[1], .25*sat(h/a + .5));
  vec3 c = mix(deep, skyW(r, sd), sat(fr*1.4 + .15));
  float fog = 1. - exp(-t*.025);
  c = mix(c, skyW(vec3(rd.x, .01, rd.z), sd), fog);
  return c;
}

float treeline(float x, float k){
  float sc = 70. - 12.*k;
  float g = x*sc + k*13.;
  float id = floor(g), f = g - id;
  float best = -9.;
  for (int i = -1; i <= 1; i++) {
    float c = id + float(i);
    float cx = c + .5 + .35*(h21(vec2(c, k)) - .5);
    float hh = (.55 + .45*h21(vec2(c, k + 7.)));
    float dx = abs(g - cx);
    // a pine: a narrow cone with ragged tiers of branches
    float tier = .06*abs(sin((g - cx)*0. + hh*40. + c)) ;
    float prof = hh*(1. - dx/(.5 + .08*hh)) - .03*abs(sin((1. - dx)*7. + c));
    best = max(best, prof);
  }
  return best/sc*2.2;
}
float ridge(float x, float k){ return .32 - .27*k + .1*sin(x*(.8 + .25*k) + k*2.3) + .05*sin(x*2.1 - k) + .02*gn(vec2(x*2., k)); }
vec3 wall(vec2 p){
  vec3 sky = mix(u_pal[5], u_pal[4], s01(.0, .9, p.y));
  sky = mix(sky, u_pal[5], .5*exp(-length(p - vec2(-.9, .55))*1.4));
  vec3 col = sky;
  float fg = mix(.35, .95, u_opt);
  for (int j = 0; j < 5; j++) {
    float k = float(j);
    // each row moves with the viewer by its nearness (Perspective)
    vec2 pk = p + u_tilt*(k/4.);
    float base = ridge(pk.x, k);
    float top = base + treeline(pk.x, k)*(1. + .25*k);
    float a = cover(pk.y - top);
    float u = k/4.;
    vec3 c = mix(u_pal[3], u_pal[0], u);
    c.x += .02*gn(vec2(pk.x*60., pk.y*30.))*u;
    // mist lies in the hollows: the lower part of every row sinks into it
    float dep = sat((top - pk.y)/(.25 + .1*k));
    float fogA = mix(.9, .25, u)*fg + (1. - u)*.1;
    c = mix(c, mix(u_pal[4], u_pal[5], .4), sat(fogA*(.55 + .45*(1. - dep)) + fg*.5*dep*dep*(1. - u*.5)));
    c = mix(c, u_pal[5], .15*fg*exp(-length(p - vec2(-.9, .55))*1.2)*(1. - u));
    col = mix(col, c, a);
  }
  return col;
}

vec2 vorL(vec2 x){
  vec2 n = floor(x), f = x - n;
  float d1 = 8., d2 = 8.;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 g = vec2(float(i), float(j));
    vec2 r = g + h22(n + g) - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
  }
  return vec2(sqrt(d1), sqrt(d2));
}
vec3 wall(vec2 p){
  // soft daylight behind, out of focus
  vec3 bg = mix(u_pal[0], u_pal[1], s01(-1.2, 1., p.y*.6 - p.x*.4));
  bg = mix(bg, u_pal[1], .4*exp(-length(p - vec2(-1.2, .7))*1.2));
  // the leaf: a long pointed blade crossing the frame from the lower right
  vec2 o = vec2(1.9, -1.15);
  vec2 ax = normalize(vec2(-1., .62));
  vec2 q = p - o;
  float u = dot(q, ax), v = dot(q, vec2(-ax.y, ax.x));
  float Ll = 3.6;
  float s = sat(u/Ll);
  float wdt = 1.05*pow(s, .55)*pow(1. - s, .85)*1.9;
  v += .06*sin(u*1.3)*s;
  float edge = abs(v) - wdt;
  edge += .006*sin(u*90.)*s01(.0, .2, s);
  float a = s01(pxu(), -pxu(), edge)*step(0., u)*step(u, Ll - .02);
  float vn = mix(.4, 1., u_opt);
  // the colour of the light through the blade, brightest away from its edges
  float fromE = sat(-edge/max(wdt, .01));
  vec3 lam = mix(u_pal[2], u_pal[4], .3 + .5*fromE);
  lam = mix(lam, u_pal[3], .3*s01(.0, 1., fbm3(p*1.5 + 3.)));
  // midrib and the secondary veins sweeping out towards the tip
  float rib = exp(-abs(v)/(.012 + .02*(1. - s)));
  float ph = (u - abs(v)*1.15)*4.2;
  float sec = exp(-abs(fract(ph) - .5)/(.035 + .02*(1. - fromE)))*s01(.02, .08, abs(v));
  vec2 vr = vorL(vec2(u, v)*13.);
  float ter = exp(-(vr.y - vr.x)/.06)*.6;
  vec2 vr2 = vorL(vec2(u, v)*38. + 5.);
  float qua = exp(-(vr2.y - vr2.x)/.08)*.35;
  float veins = sat(rib + .8*sec + (ter + qua)*vn);
  vec3 c = mix(lam, u_pal[5], veins*.55*vn + rib*.25);
  // the areoles between the veins hold a little more colour
  c = mix(c, u_pal[2], .18*(1. - veins)*vn);
  c = dim(c, .25*s01(.0, -.03, edge)*s01(-.06, .0, edge));
  return mix(bg, c, a);
}

vec3 wall(vec2 p){
  vec2 C = vec2(.62, .3);
  vec2 d = p - C;
  float r = length(d);
  float th = atan(d.y, d.x);
  float tight = mix(.95, 1.6, u_opt);
  // one turn of the stair per floor: each floor up is a ring closer to the skylight
  float lr = log(r);
  float s = th/(2.*PI) - lr*tight;
  float f = fract(s);
  float fw = (pxu()/r)*tight/(2.*PI)*2.5 + .002;
  float up = sat(-lr*.45 + .2);
  float rise = s01(1.4, -.3, lr);
  // the light comes down the well from the skylight: everything brightens and pales towards it
  vec3 plaster = mix(u_pal[1], u_pal[3], rise);
  float face = .5 + .5*cos(th - 2.3);
  // the underside of each flight, with the line of every step on it
  float st = fract(th/(2.*PI)*18. - lr*tight*18.);
  vec3 under = mix(plaster, u_pal[2], .25);
  under.x += .06*face*(1. - rise*.5) - .03*s01(.82, 1., st)*(1. - rise) + .015*s01(.0, .15, st)*(1. - rise);
  // the outer wall seen between the flights, deeper and in shade
  vec3 wallc = dim(mix(plaster, u_pal[0], .35*(1. - rise)), .08);
  wallc.x += .03*face;
  float uMask = s01(.06 - fw, .06 + fw, f)*s01(.52 + fw, .52 - fw, f);
  vec3 c = mix(wallc, under, uMask);
  // the rail: a pale band catching the skylight, with a soft shadow under it
  float rail = s01(.06 + fw, .06 - fw, f)*s01(.0 - fw, .0 + fw, f) + s01(.0 + .0, .0 - .0, f)*0.;
  float railB = 1. - s01(.0, .06 + fw, f);
  vec3 rc = mix(u_pal[4], u_pal[5], .5 + .5*face);
  c = mix(c, rc, sat(railB)*s01(.0, fw*2., f));
  c = dim(c, .2*exp(-(f - .06)/.04)*step(.06, f)*uMask);
  c.x += .006*gn(p/cssu()*.3);
  // the skylight and the haze around it
  float sky = exp(-r/.07);
  c = mix(c, mix(plaster, u_pal[5], .6), s01(.25, .02, r));
  c = mix(c, u_pal[5], sky);
  c = dim(c, .1*s01(1., 2.4, r));
  return c;
}

vec3 wall(vec2 p){
  float hz = .2;
  float sh = mix(.3, 1., u_opt);
  vec2 sun = vec2(-1.05, hz + mix(.04, .3, u_opt));
  float y = p.y - hz;
  vec3 sky = mix(u_pal[4], u_pal[3], s01(.0, .3, y));
  sky = mix(sky, u_pal[0], s01(.25, 1.1, y));
  sky = mix(sky, u_pal[4], .6*exp(-length((p - sun)*vec2(.5, 1.))*2.));
  sky = mix(sky, lift(u_pal[4], .05), cover(length(p - sun) - .05)*.9);
  if (y >= 0.) return sky;
  float dz = -y;
  float Z = .55/(dz + .004);
  // the rows run straight away from you, a little to the right of the frame
  float X = (p.x - .35)*Z;
  float rw = .9;
  float u = X/rw - floor(X/rw);
  float prof = sat(1. - pow(abs(u - .5)*2.08, 3.));
  // each row is a line of round bushes: lumpy along its length
  float bump = .5 + .5*gn(vec2(floor(X/rw)*3.1, Z*1.6));
  float top = prof*(.8 + .25*bump);
  float soil = 1. - s01(.0, .12, top);
  vec3 bush = mix(u_pal[1], u_pal[2], top);
  bush.x += (.05*gn(vec2(X*7., Z*11.)) + .03*gn(vec2(X*19., Z*30.)))*s01(.0, .3, dz);
  bush = mix(bush, u_pal[0], .35*(1. - top));
  // the low sun lights the side of each row that faces it, and the tops
  float face = sat((.5 - u)*2.)*top;
  bush = mix(bush, u_pal[3], sat(face*.55*sh + .2*top*sh)*(1. - .5*s01(.0, .6, dz)));
  vec3 ground = mix(u_pal[5], dim(u_pal[5], .2), .5 + .5*gn(vec2(X*3., Z*2.)));
  vec3 c = mix(bush, ground, soil*s01(.0, .15, dz));
  // far away the rows merge into one soft colour
  float far = exp(-dz*9.);
  c = mix(c, mix(u_pal[2], u_pal[4], .3), far*.9);
  c = mix(c, sky, exp(-dz*40.)*.8);
  return c;
}

float branch(vec2 p){
  // a few curving twigs and clusters of palmate leaves, as a soft shadow
  float d = 9.;
  vec2 q = p - vec2(1.6, .9);
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    vec2 dir = normalize(vec2(-1., -.35 - .25*fi));
    float u = clamp(dot(q, dir), 0., 1.2 - .2*fi);
    vec2 c = dir*u + vec2(0., .06*sin(u*3. + fi));
    d = min(d, length(q - c) - .012*(1.3 - u*.5));
    for (int j = 0; j < 3; j++) {
      float fj = float(j);
      vec2 lc = dir*(.35 + .3*fj) + vec2(.05*sin(fi*3. + fj), .08*cos(fi + fj*2.));
      vec2 lq = q - lc;
      float a = atan(lq.y, lq.x) + fi + fj;
      float r = length(lq);
      float leaf = r - .1*(.55 + .45*pow(abs(cos(a*2.5)), .6));
      d = min(d, leaf);
    }
  }
  return d;
}
vec3 wall(vec2 p){
  float sh = mix(.35, 1., u_opt);
  // the glow of the paper, brightest where the garden light is strongest
  vec3 paper = mix(u_pal[2], u_pal[4], s01(-1.2, 1.2, p.x*.5 + p.y*.6 + .2));
  vec2 w = p/cssu();
  paper.x += .008*gn(w*.06) + .006*gn(w*.25)*0. + .01*fbm3(p*6.);
  // the shadow of the branch: soft, because it is a little way behind the paper
  float bd = branch(p);
  float s = s01(.06, -.03, bd)*sh;
  paper = mix(paper, mix(u_pal[1], u_pal[2], .5), .55*s);
  // the lattice: thin wooden bars, with the sliding panels' wider frames
  vec2 g = vec2((p.x + 2.)/.32, (p.y + 1.)/.26);
  vec2 f = abs(g - floor(g + .5));
  float bar = cssu()*1.6/.3;
  float lat = max(s01(bar*1.5, bar*.6, f.x), s01(bar*1.8, bar*.7, f.y));
  float frame = s01(.035, .025, abs(p.x - .55)) + s01(.035, .025, abs(p.x + 1.05));
  vec3 wood = mix(u_pal[5], u_pal[2], .3);
  vec3 c = mix(paper, wood, lat*.75);
  c = mix(c, dim(wood, .1), sat(frame));
  c = dim(c, .12*s01(.8, 2.2, length(p*vec2(.6, 1.))));
  return c;
}

float bergH(float x, vec3 b){
  // a tabular or rounded berg: broad, with a ragged faceted top
  float u = (x - b.x)/b.y;
  // steep calving faces at both ends, a broad top that tilts a little and is broken into steps
  float side = s01(1., .82 + .06*gn(vec2(x*8., b.z)), abs(u));
  float top = .78 + .14*u*(fract(b.z*13.) - .5)*2. + .06*floor(2.5 + 2.5*gn(vec2(x*2.2, b.z*5.)))/5. + .03*gn(vec2(x*14., b.z));
  return b.y*b.z*top*side*step(abs(u), 1.);
}
float bergF(float x, float y, vec3 b){
  // the berg's face: flat facets, each turned a little differently to the low light
  vec2 q = vec2(x*6., y*4.5) + b.z*9.;
  vec2 n = floor(q), f = q - n;
  float md = 8., id = 0.;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 g = vec2(float(i), float(j));
    vec2 r = g + h22(n + g) - f;
    float d = dot(r, r);
    if (d < md) { md = d; id = h21(n + g); }
  }
  return id*1.6 - .8 + .15*gn(vec2(x*30., y*30.));
}
vec3 wall(vec2 p){
  float hz = -.05;
  float hzz = mix(.25, .85, u_opt);
  vec3 sky = mix(u_pal[5], u_pal[1], s01(.0, .45, p.y - hz));
  sky = mix(sky, u_pal[0], s01(.35, 1.1, p.y - hz));
  float dz = hz - p.y;
  bool water = dz > 0.;
  float yy = water ? hz + dz : p.y;
  vec3 col = sky;
  if (water) {
    col = mix(u_pal[5], u_pal[1], s01(.0, .45, dz));
    col = mix(col, u_pal[0], s01(.35, 1.1, dz));
    col = dim(col, .08 + .1*s01(.0, .8, dz));
    col.x += .01*gn(vec2(p.x*2., dz*80./(dz + .1)));
  }
  for (int k = 0; k < 4; k++) {
    float fk = float(k);
    vec3 b = k == 0 ? vec3(-1.15, .32, .55) : k == 1 ? vec3(.85, .55, .62) : k == 2 ? vec3(1.75, .22, .5) : vec3(-.15, .1, .6);
    float far = k == 1 ? 0. : k == 3 ? 1. : .5;
    float bb = hz;
    float h = bergH(p.x + (water ? .003*gn(vec2(p.y*90., fk)) : 0.), b);
    float up = yy - bb;
    float a = cover(up - h)*step(.001, h);
    float fct = bergF(p.x, yy, b);
    vec3 ice = mix(u_pal[3], u_pal[4], .3 + .45*s01(-.6, .8, fct));
    ice = mix(ice, u_pal[2], .25*s01(.1, -.6, fct) + .3*s01(.6*h, .0, up));
    ice.x += .025*gn(vec2(p.x*60., yy*4.));
    ice.x += .03*exp(-abs(h - up)/.01);
    ice = mix(ice, sky, hzz*(.15 + .5*far));
    if (water) ice = mix(dim(ice, .15), col, .25);
    col = mix(col, ice, a);
    // the drowned foot of the berg glowing turquoise just under the surface
    float foot = water ? exp(-dz/.05)*s01(1.25, .9, abs(p.x - b.x)/b.y)*(1. - a) : 0.;
    col = mix(col, u_pal[2], .45*foot*(1. - far*.6));
  }
  return col;
}

vec3 wall(vec2 p){
  vec2 C = vec2(.72, -.12);
  // fine pale gravel all round
  vec2 w = p/cssu();
  vec3 col = mix(u_pal[0], u_pal[5], .45 + .2*gn(w*.05));
  col.x += .03*gn(w*.18) + .02*gn(w*.5);
  float bl = mix(.2, 1., u_opt);
  const float N = 34.;
  for (int k = 33; k >= 0; k--) {
    float i = float(k);
    float t = (i + .5)/N;
    float a = i*2.39996 + .3;
    vec2 dir = vec2(cos(a), sin(a));
    float L = .16 + 1.05*pow(t, .8);
    float W = L*(.42 - .1*t);
    vec2 q = p - C;
    float u = dot(q, dir)/L;
    float v = dot(q, vec2(-dir.y, dir.x));
    // a thick leaf: narrow at its base, broad near the end, drawn to a short point
    float prof = W*pow(sat(u), .55)*pow(sat(1. - u), .42)*1.45;
    float d = abs(v) - prof;
    float inL = step(0., u)*step(u, 1.);
    float a1 = s01(pxu()*1.2, -pxu()*1.2, d)*inL;
    // the soft shadow it lays on what lies under it
    float sh = s01(.06, -.01, d + .015)*inL*(1. - a1);
    col = dim(col, .35*sh);
    if (a1 > 0.) {
      float x = v/max(prof, 1e-3);
      // cupped: the midline sits low and the rims catch the light
      vec3 n = normalize(vec3(-dir.y*x*1.4 - dir.x*(u - .55)*1.2, dir.x*x*1.4 - dir.y*(u - .55)*1.2, 1.));
      float kk = sat(dot(n, normalize(vec3(-.5, .6, .65))));
      kk = kk*kk*(3. - 2.*kk);
      vec3 c = mix(u_pal[1], u_pal[3], .3 + .6*kk);
      c = mix(c, u_pal[2], .35*(1. - t));
      // the waxy bloom, paler on the older outer leaves
      c = mix(c, mix(u_pal[3], u_pal[5], .3), .3*t*s01(.2, 1., kk));
      // the blush at the tip and along the rim
      float tip = s01(.75, 1., u) + .35*s01(.75, 1., abs(x))*s01(.4, .9, u);
      c = mix(c, u_pal[4], sat(tip*bl*.85));
      c.x -= .05*s01(.15, .0, u)*(1. - t);
      c.x += .012*gn(q*40. + i);
      col = mix(col, c, a1);
    }
  }
  col = dim(col, .1*s01(.9, 2.2, length(p - C)));
  return col;
}

vec3 wall(vec2 p){
  float hz = -.42;
  float y = p.y - hz;
  vec3 sky = mix(u_pal[3], u_pal[2], s01(.0, .25, y));
  sky = mix(sky, u_pal[1], s01(.15, .8, y));
  sky = mix(sky, u_pal[0], s01(.7, 1.5, y));
  vec2 mc = vec2(.85, hz + mix(.18, .85, u_opt));
  float R = .25;
  vec2 q = (p - mc)/R;
  float r = length(q);
  // the glow of the moon in the air
  sky = mix(sky, u_pal[4], .25*exp(-max(r - 1., 0.)*.9));
  // the moon: seas and highlands, the limb a touch darker, warmed and dimmed the lower it hangs
  float maria = s01(.05, .5, fbm3(q*1.3 + 2.) + .2*gn(q*3.));
  vec3 moon = mix(u_pal[4], mix(u_pal[4], u_pal[3], .55), maria*.55);
  moon.x -= .05*pow(r, 4.) - .02*gn(q*9.);
  float low = s01(.9, .2, mc.y - hz);
  moon = mix(moon, u_pal[3], .45*low);
  vec3 col = mix(sky, moon, s01(1. + pxu()/R*1.2, 1. - pxu()/R*1.2, r));
  // a thin band of cloud across the moon and the sky, lit from behind where it crosses the disc
  float cb = exp(-pow((p.y - mc.y + .05 + .06*sin(p.x*1.4))/.035, 2.))*s01(.15, .7, fbm3(vec2(p.x*1.6, p.y*9.)) + .3);
  vec3 cc = mix(u_pal[1], u_pal[2], .5);
  cc = mix(cc, u_pal[4], .45*exp(-max(r - .8, 0.)*2.5));
  col = mix(col, cc, cb*.8);
  // the far low coast and the sea below it, with the moon's path
  float coast = hz + .025 + .02*s01(-.3, .5, gn(vec2(p.x*1.5, 1.))) + .006*gn(vec2(p.x*12., 2.));
  vec3 land = mix(u_pal[5], u_pal[1], .25);
  col = mix(col, land, cover(p.y - coast)*step(hz - .002, p.y));
  if (p.y < hz) {
    float dz = hz - p.y;
    vec3 sea = mix(u_pal[2], u_pal[0], s01(.0, .6, dz));
    float path = exp(-abs(p.x - mc.x)/(.06 + .25*dz))*(.5 + .5*gn(vec2(p.x*8., dz*120./(dz + .05))));
    sea = mix(sea, u_pal[4], .55*path*exp(-dz*1.5));
    col = sea;
  }
  return col;
}

vec3 wall(vec2 p){
  vec2 C = vec2(1.05, -.5);
  vec2 q = (p - C)*vec2(1., 1.18)/1.7;
  vec2 dq = normalize(q + 1e-5);
  float r = length(q) + .05*gn(dq*2.) + .025*gn(q*3.);
  // bands of colour from the deep eye outwards
  vec3 c = mix(u_pal[0], u_pal[1], s01(.12, .32, r));
  c = mix(c, u_pal[2], s01(.32, .4, r));
  c = mix(c, u_pal[3], s01(.42, .5, r));
  c = mix(c, u_pal[4], s01(.52, .62, r));
  // the mats run out in fine streamers over the crust, following the flow
  float rays = .5 + .3*gn(dq*26. + r*.6) + .15*gn(dq*70. + r*1.5) + .2*fbm3(p*2.);
  float mat = s01(1.35 + .3*gn(dq*3. + 4.), .6, r)*s01(.5, .7, r);
  vec3 crust = u_pal[5];
  crust.x += .03*fbm3(p*3.) + .015*gn(p/cssu()*.2);
  vec3 col = c;
  col = mix(col, mix(crust, u_pal[4], .4*rays), s01(.6, .7, r));
  col = mix(col, crust, s01(.85, 1.6, r - .25*mat*rays));
  // the eye is deep: darker and clearer towards its middle, with the rim of sinter catching the light
  col = dim(col, .25*s01(.25, .0, r));
  col = mix(col, u_pal[5], .3*exp(-pow((r - .345)/.012, 2.)));
  // steam drifting off the water
  float st = s01(.0, .8, fbm(p*1.2 + vec2(3., 1.)))*exp(-r*.9)*mix(.15, .7, u_opt);
  col = mix(col, mix(u_pal[5], u_pal[2], .2), st);
  return col;
}

float snH(vec2 x, float a){
  vec2 w = x + .6*vec2(gn(x*.15), gn(x*.15 + 4.));
  float h = .5*gn(vec2(w.x*.35, w.y*.9)) + .25*gn(vec2(w.x*.8, w.y*1.9) + 3.);
  // sastrugi: the wind leaves sharper lips on one side of each drift
  h += .08*s01(-.2, .5, gn(vec2(w.x*1.6, w.y*3.4) + 7.));
  return h*a;
}
vec3 wall(vec2 p){
  vec3 ro = vec3(0., .9, 0.);
  vec3 rd = normalize(vec3(p.x, p.y - .16, 2.));
  float a = mix(.25, .7, u_opt);
  float y = rd.y;
  vec3 sky = mix(mix(u_pal[5], u_pal[3], .45), u_pal[3], s01(-.02, .25, y));
  sky = mix(sky, u_pal[1], s01(.1, .5, y));
  sky = mix(sky, u_pal[0], s01(.35, .9, y));
  if (y >= 0.) return sky;
  float t = -ro.y/y;
  for (int i = 0; i < 3; i++) { vec3 x = ro + rd*t; t = (snH(x.xz, a) - ro.y)/y; }
  vec3 x = ro + rd*t;
  float e = .02 + .004*t;
  float h = snH(x.xz, a);
  vec3 n = normalize(vec3(-(snH(x.xz + vec2(e, 0.), a) - h)/e, 1., -(snH(x.xz + vec2(0., e), a) - h)/e));
  // lit only by the sky: the faces turned to the bright west keep a little rose
  float west = sat(dot(n, normalize(vec3(-.9, .45, .6))));
  float up = n.y;
  vec3 c = mix(u_pal[1], u_pal[3], s01(.6, 1., up));
  c = mix(c, u_pal[4], .5*s01(.85, 1., up));
  c = mix(c, u_pal[5], .3*west*west);
  // sparkle of the crust, at its real size
  c.x += .02*gn(vec2(x.x, x.z)*30.)*exp(-t*.15);
  float fog = 1. - exp(-t*.06);
  c = mix(c, mix(sky, u_pal[3], .3), fog*.95);
  return c;
}

vec3 wall(vec2 p){
  vec2 C = vec2(.72, .3);
  float R = .2;
  vec2 q = p - C;
  float r = length(q)/R;
  vec2 dq = normalize(q + 1e-5);
  float co = mix(.5, 1.2, u_opt);
  // the twilight sky of totality, brighter all round the horizon
  vec3 sky = mix(u_pal[2], u_pal[1], s01(-1., -.2, p.y));
  sky = mix(sky, u_pal[0], s01(-.3, .9, p.y));
  sky = mix(sky, u_pal[5], .35*s01(-.6, -1., p.y));
  // the corona: soft streamers, longest along the sun's equator
  float eq = .6 + .4*abs(dot(dq, normalize(vec2(1., .25))));
  float st = .55 + .45*gn(dq*7.) + .25*gn(dq*19.);
  float cor = exp(-(r - 1.)/(.25 + .55*eq*st*co))*s01(.98, 1.02, r);
  float inner = exp(-(r - 1.)/.06)*s01(.98, 1.01, r);
  vec3 col = mix(sky, u_pal[3], sat(cor*.75));
  col = mix(col, u_pal[4], sat(inner*.9));
  // the chromosphere: a thin rose edge showing on one side, and a prominence
  float chrom = exp(-pow((r - 1.005)/.006, 2.))*s01(-.2, .6, dot(dq, normalize(vec2(-.8, -.4))));
  col = mix(col, u_pal[5], .8*chrom);
  vec2 pr = q/R - normalize(vec2(-.7, -.6))*1.02;
  col = mix(col, u_pal[5], .7*exp(-dot(pr, pr)/.0008));
  // the moon
  vec3 moon = dim(u_pal[0], .3);
  return mix(col, moon, s01(1. + pxu()/R*1.2, 1. - pxu()/R*1.2, r));
}

// where chips may lie: open ground behind the middle of the window, chips gathering towards the right and the lower corner
float chipMask(vec2 p){
  float calm = s01(.3, 1.15, length((p - vec2(-.3, .2))*vec2(.72, 1.)));
  return (.15 + .85*calm)*(.8 + .25*gn(p*.9 + 3.));
}
// one layer of chips: broken stones from a jittered grid, each its own colour and grain
void chips(inout vec3 c, vec2 p, float sc, float dens, float seed){
  vec2 g = p*sc + seed;
  vec2 cell = floor(g);
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 cc = cell + vec2(float(i), float(j));
    vec2 ctr = cc + .5 + .5*(h22(cc + seed) - .5);
    float on = step(1. - dens*chipMask((ctr - seed)/sc), h21(cc + seed*3.));
    vec2 q = rot(6.28*h21(cc + 1.3 + seed))*(g - ctr);
    float r = .22 + .2*h21(cc + 7.1 + seed);
    float d = sdBox(q, vec2(r, r*(.6 + .35*h21(cc + 2.2))), .015);
    d = max(d, dot(q, normalize(vec2(1., 1.3))) - r*.78);
    d = max(d, dot(q, normalize(vec2(-1.2, .4 + h21(cc + 5.5)))) - r*.86);
    float a = s01(pxu()*sc*1.1, -pxu()*sc*1.1, d)*on;
    float k = h21(cc + 9.9 + seed);
    vec3 sc3 = k < .3 ? u_pal[1] : k < .55 ? u_pal[2] : k < .78 ? u_pal[3] : u_pal[4];
    // marble inside each chip: a soft cloud and a fine vein, the way a ground stone shows its grain
    sc3.x += .04*(h21(cc + 4.4) - .5) + .035*fbm3(q*3.5 + cc) - .03*exp(-abs(gn(q*2.2 + cc*1.7))/.04);
    // a hairline of the darker cement where the stone meets the ground
    sc3 = mix(sc3, dim(u_pal[0], .2), .35*s01(-pxu()*sc*2.5, 0., d));
    c = mix(c, sc3, a);
  }
}
vec3 wall(vec2 p){
  float dn = mix(.35, .8, u_opt);
  vec3 c = u_pal[0];
  c.x += .008*gn(p/cssu()*.3) + .01*fbm3(p*3. + 2.);
  // fine aggregate in the ground, very faint
  vec2 w = p/cssu();
  float grit = step(.9, h21(floor(w*.45)))*(.4 + .6*chipMask(p));
  c = mix(c, u_pal[5], .16*grit);
  vec3 base = c;
  chips(c, p, 15., dn*.35, 2.);
  c = mix(base, c, .35);
  base = c;
  chips(c, p, 6.5, dn*.42, 5.);
  c = mix(base, c, .65);
  chips(c, p, 2.6, dn*.55, 11.);
  // the polish: a soft window reflected in the floor and a gentle falloff to the corners
  float win = s01(.35, .0, abs(p.x*.45 - p.y + .2) - .3)*s01(1.6, .4, abs(p.x + .3));
  c = lift(c, .04*win);
  c = dim(c, .1*s01(.7, 2.2, length(p*vec2(.6, 1.))));
  return c;
}

float ell(vec2 q, vec2 r){ return (length(q/r) - 1.)*min(r.x, r.y); }
vec3 wall(vec2 p){
  float gw = mix(.6, 1.2, u_opt);
  vec2 C = vec2(.82, .1);
  float R = .5, sq = .86;
  float px = pxu()/R;
  // the room: a plain wall, warmed by the lantern's light where it is near
  vec3 col = mix(u_pal[0], u_pal[1], s01(-1.3, 1., p.y*.4 - p.x*.2));
  float dl = length((p - C)*vec2(.8, 1.));
  col = mix(col, u_pal[5], sat(.85*gw*exp(-dl*1.1)));
  col = mix(col, u_pal[2], sat(.45*gw*exp(-dl*2.)));
  vec2 q = (p - C)/R;
  q.y /= sq;
  // the paper is cut off at each end: a ring of wire holds the opening, seen a little from below
  float yc = .8, wc = sqrt(1. - yc*yc), tilt = .16;
  vec2 qt = q - vec2(0., yc), qb = q + vec2(0., yc);
  // the cord and the wire bail that carries the lantern from the top ring
  vec3 wire = dim(u_pal[0], .3);
  float cy = yc*sq*R + C.y;
  col = mix(col, wire, s01(.006, .002, abs(p.x - C.x))*step(cy + .09, p.y));
  vec2 bp = p - vec2(C.x, cy + .09);
  float bail = abs(abs(bp.x) - (wc*R)*sat(-bp.y/.09)) - .0015;
  col = mix(col, wire, s01(.003, .0, bail)*step(-.09, bp.y)*step(bp.y, 0.));
  float body = s01(px*1.4, -px*1.4, length(q) - 1.)*s01(px, -px, abs(q.y) - yc);
  // the openings: the top one shows the rim from below as a thin line, the bottom one its lit inside
  float capB = s01(px, -px, ell(qb, vec2(wc, wc*tilt)));
  float capT = s01(px, -px, ell(qt, vec2(wc, wc*tilt)))*step(0., qt.y);
  float a = max(body, max(capB, capT));
  if (a > 0.) {
    float r = length(q);
    float z = sqrt(max(1. - r*r, 0.));
    // brightest where the paper faces you and you see the bulb through one layer
    vec3 c = mix(u_pal[2], u_pal[3], s01(.0, .6, z));
    c = mix(c, u_pal[4], s01(.55, 1., z)*.9);
    c = dim(c, .1*s01(.0, -.9, q.y));
    float lat = asin(clamp(q.y, -1., 1.))/1.5708;
    float rib = exp(-pow((fract(lat*9. + .5) - .5)/.06, 2.));
    c = dim(c, (.06 + .14*(1. - z))*rib);
    c.x += .012*gn(q*vec2(40., 8.)) + .01*gn(p/cssu()*.3);
    // light falls off as the paper turns towards each opening, and less of it gets through the doubled fold
    float ay = abs(q.y);
    c = mix(c, mix(u_pal[2], u_pal[1], .3), .45*s01(.45, yc, ay));
    float fold = s01(yc - .075, yc - .055, ay);
    float az = atan(q.x, z + .001);
    float pleat = .5 + .5*sin(az*48.);
    c = mix(c, dim(u_pal[2], .18), fold*(.55 + .2*pleat));
    c.x += .02*fold*pleat*(1. - .5*abs(q.x)/wc);
    c = dim(c, .25*s01(.8, 1., r));
    // the bottom opening: the inside of the paper, lit, deepest at the back
    vec3 inside = mix(u_pal[3], u_pal[4], .6*s01(-.2, .8, -qb.y/(wc*tilt)));
    inside = dim(inside, .25*s01(.6, 1., length(qb/vec2(wc, wc*tilt))));
    c = mix(c, inside, capB*step(-yc, q.y));
    c = mix(c, inside, capB*s01(-yc + px, -yc - px, q.y));
    // the top opening is hidden from below: only the paper folded over the far side of its rim shows
    c = dim(c, .12*capT);
    // the wire rings: a thin dark line with a pin of light where it faces the room
    float wr = min(abs(ell(qt, vec2(wc, wc*tilt))), abs(ell(qb, vec2(wc, wc*tilt))));
    float wline = s01(px*1.6, px*.4, wr);
    float hi = s01(.3, .9, -q.x/wc)*s01(px*.8, 0., wr);
    vec3 wc3 = mix(wire, u_pal[4], .5*hi);
    c = mix(c, wc3, wline);
    col = mix(col, c, a);
  }
  return col;
}

float drapeL(vec2 p){ return .55*sin(p.x*1.1 + .8*sin(p.y*.9 + 1.)) + .3*sin(p.x*2.3 - p.y*.6 + 2.) + .25*fbm3(p*.7 + 3.); }
vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .3*p.x - .3*p.y));
  c = mix(c, u_pal[2], .6*exp(-dot(p - vec2(-1.1, .9), p - vec2(-1.1, .9))*.35));
  c = mix(c, u_pal[3], .35*s01(.8, 2.4, length(p - vec2(-.4, .4))));
  float e = .01;
  float h = drapeL(p);
  vec2 gd = vec2(drapeL(p + vec2(e, 0.)) - h, drapeL(p + vec2(0., e)) - h)/e;
  c.x += .045*dot(gd, normalize(vec2(-.6, .8)));
  vec2 q = p/cssu();
  float per = mix(3.6, 6.5, u_opt);
  float tx = q.x/per + .35*gn(vec2(q.y*.006 + .29, 1.41)), ty = q.y/per + .35*gn(vec2(2.37, q.x*.006 + .61));
  float ix = floor(tx), iy = floor(ty);
  float fx = abs(fract(tx) - .5)*2., fy = abs(fract(ty) - .5)*2.;
  float twx = .5 + .42*s01(-.3, .7, gn(vec2(ix*.71 + .37, q.y*.018 + .53))), twy = .5 + .42*s01(-.3, .7, gn(vec2(q.x*.018 + .53, iy*.71 + .37)));
  float wx = 1. - s01(twx*.7, twx, fx), wy = 1. - s01(twy*.7, twy, fy);
  float over = mod(ix + iy, 2.);
  float top = mix(wy, wx, over);
  float gap = (1. - wx)*(1. - wy);
  float idv = .5*(h21(vec2(ix, 3.)) + h21(vec2(7., iy))) - .5;
  float k = mix(1., .85, u_dark);
  c.x += k*(.022*(top - .5) - .035*gap + .022*idv + .012*(twx + twy - 1.));
  c.x += .006*fbm3(p*3.);
  return c;
}

float fibreW(vec2 q, float a, float s){
  vec2 r = rot(a)*q;
  float v = gn(vec2(r.x*.01, r.y*.16) + s) + .4*gn(vec2(r.x*.03, r.y*.3) + s*2.);
  return exp(-abs(v)*10.)*s01(-.2, .6, gn(r*.008 + s*3.));
}
vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .25*p.x - .35*p.y));
  c = mix(c, u_pal[2], .5*exp(-dot(p - vec2(-.9, .8), p - vec2(-.9, .8))*.4));
  float form = fbm(p*2.6 + 4.);
  c.x += .026*form;
  c.yz *= 1. + .12*form;
  vec2 q = p/cssu();
  float fb = fibreW(q, .3, 1.) + fibreW(q, -.9, 7.) + fibreW(q, 1.6, 13.) + .7*fibreW(q*1.6, 2.4, 21.);
  float k = mix(.5, 1.4, u_opt)*mix(1., .75, u_dark);
  c.x += .04*sat(fb)*k;
  c.x += .004*gn(q*.08);
  vec2 cl = floor(q/70.);
  vec2 cp = (cl + .2 + .6*h22(cl + 5.))*70.;
  vec2 dq = rot(h21(cl + 2.)*6.28)*(q - cp);
  float fl = exp(-dot(dq*vec2(.3, 1.2), dq*vec2(.3, 1.2))/(2. + 6.*h21(cl + 8.)));
  c = mix(c, dim(u_pal[3], .2), fl*step(.62, h21(cl + 3.3))*.4*mix(.5, 1., u_opt));
  float fd = dot(p, normalize(vec2(.94, .34))) - .35;
  float side = s01(-.005, .005, fd);
  c.x += .016*side - .008;
  c.x += .025*exp(-abs(fd)/.012)*(1. - side) - .02*exp(-abs(fd)/.035)*side;
  c = mix(c, u_pal[3], .25*s01(.9, 2.3, length(p)));
  return c;
}

vec3 wall(vec2 p){
  float hz = -.22;
  float t = sat((p.y - hz)/1.2);
  vec3 c = mix(u_pal[2], u_pal[1], sm1(t*2.2));
  c = mix(c, u_pal[0], sm1(t*1.5 - .4));
  vec2 sp = vec2(.38, hz + .04);
  float g = mix(.35, .85, u_opt);
  c = mix(c, u_pal[4], g*(.55*exp(-length((p - sp)*vec2(.55, 1.))*2.6) + .35*exp(-length(p - sp)*9.)));
  if (p.y < hz) {
    float dy = hz - p.y;
    vec3 s = mix(u_pal[3], u_pal[5], sm1(dy/.8));
    s = mix(s, mix(u_pal[2], u_pal[1], .3), .45*exp(-dy*5.));
    float col_ = exp(-abs(p.x - sp.x)*(2.2 + dy*3.))*exp(-dy*2.2);
    float st = .5 + .5*gn(vec2(p.x*3., p.y*55./(dy + .3)));
