  float win = (1. - s01(-.05, .05, sdBox(rp, vec2(.45, .7), .2)))*exp(-dot(rp, rp)*.5);
  float sh = mix(.35, 1.2, u_opt);
  tc.x += .035*dot(nxy, L2);
  tc = mix(tc, u_pal[4], sat(win*.5*sh));
